package main

import (
	"fmt"
	"strconv"
	"strings"
	"unicode/utf8"
)

// Minimal YAML subset parser sufficient for cheat config/frontmatter.

type yKind int

const (
	yScalar yKind = iota
	ySeq
	yMap
)

type yNode struct {
	Kind  yKind
	Line  int
	// scalar
	Value string // decoded (for plain: raw trimmed)
	Raw   string // plain raw token
	Style byte   // 0 plain, '\'', '"', '|', '>'
	// seq
	Items []*yNode
	// map
	Pairs []yPair
}

type yPair struct {
	Key     string
	KeyLine int
	KeyNode *yNode
	Value   *yNode
}

type yamlError struct{ msg string }

func (e *yamlError) Error() string { return e.msg }

func yamlSyntaxErr(line int, msg string) error {
	return &yamlError{msg: fmt.Sprintf("yaml: line %d: %s", line, msg)}
}
func yamlTypeErr(line int, msg string) error {
	return &yamlError{msg: fmt.Sprintf("yaml: unmarshal errors:\n  line %d: %s", line, msg)}
}

type yLine struct {
	raw     string // raw line without newline (comments intact)
	content string // after indentation, comment-stripped and right-trimmed
	indent  int
	num     int
	blank   bool
}

type yParser struct {
	lines []yLine
	pos   int
	dupErr error
}

func stripYAMLComment(s string) string {
	inS, inD := false, false
	for i := 0; i < len(s); i++ {
		c := s[i]
		if inS {
			if c == '\'' {
				if i+1 < len(s) && s[i+1] == '\'' {
					i++
				} else {
					inS = false
				}
			}
			continue
		}
		if inD {
			if c == '\\' {
				i++
				continue
			}
			if c == '"' {
				inD = false
			}
			continue
		}
		switch c {
		case '\'':
			// a quote only starts a quoted scalar at a value boundary roughly; treating apostrophes in plain text as quote could hide comments, acceptable
			if i == 0 || strings.ContainsRune(" \t:[{,", rune(s[i-1])) {
				inS = true
			}
		case '"':
			if i == 0 || strings.ContainsRune(" \t:[{,", rune(s[i-1])) {
				inD = true
			}
		case '#':
			if i == 0 || s[i-1] == ' ' || s[i-1] == '\t' {
				return strings.TrimRight(s[:i], " \t")
			}
		}
	}
	return strings.TrimRight(s, " \t")
}

func makeYLines(input string) []yLine {
	input = strings.TrimPrefix(input, "\ufeff")
	input = strings.ReplaceAll(input, "\r\n", "\n")
	input = strings.ReplaceAll(input, "\r", "\n")
	parts := strings.Split(input, "\n")
	// If input ends in newline Split gives a trailing empty element; keep it as blank (line numbers for EOF errors are approximate)
	out := make([]yLine, 0, len(parts))
	for i, p := range parts {
		indent := 0
		for indent < len(p) && p[indent] == ' ' {
			indent++
		}
		contentAfterIndent := ""
		if indent < len(p) {
			contentAfterIndent = p[indent:]
		}
		content := stripYAMLComment(contentAfterIndent)
		out = append(out, yLine{raw: p, content: content, indent: indent, num: i + 1, blank: strings.TrimSpace(content) == ""})
	}
	return out
}

func parseYAML(input string) (*yNode, error) {
	p := &yParser{lines: makeYLines(input)}
	p.skipBlank()
	// leading --- doc marker
	if p.pos < len(p.lines) && strings.TrimSpace(p.lines[p.pos].content) == "---" {
		p.pos++
	}
	node, err := p.parseBlock(0)
	if err != nil {
		return nil, err
	}
	if p.dupErr != nil {
		return nil, p.dupErr
	}
	if node == nil {
		// empty document => null scalar
		return &yNode{Kind: yScalar, Value: "", Raw: "", Line: 1}, nil
	}
	return node, nil
}

func (p *yParser) skipBlank() {
	for p.pos < len(p.lines) && p.lines[p.pos].blank {
		p.pos++
	}
}

func isDocMarker(content string) bool {
	c := strings.TrimSpace(content)
	return c == "---" || c == "..."
}

// find mapping colon in content outside quotes/flow. Returns index of ':' or -1. Colon must be followed by space/EOL or be flow context.
func findMapColon(s string) int {
	inS, inD := false, false
	depth := 0
	for i := 0; i < len(s); i++ {
		c := s[i]
		if inS {
			if c == '\'' {
				if i+1 < len(s) && s[i+1] == '\'' {
					i++
				} else {
					inS = false
				}
			}
			continue
		}
		if inD {
			if c == '\\' {
				i++
				continue
			}
			if c == '"' {
				inD = false
			}
			continue
		}
		switch c {
		case '\'':
			if i == 0 || strings.ContainsRune(" \t:[{,", rune(s[i-1])) {
				inS = true
			}
		case '"':
			if i == 0 || strings.ContainsRune(" \t:[{,", rune(s[i-1])) {
				inD = true
			}
		case '[', '{':
			depth++
		case ']', '}':
			depth--
		case ':':
			if depth == 0 {
				if i+1 >= len(s) || s[i+1] == ' ' || s[i+1] == '\t' {
					return i
				}
				// In "key:" at end already handled; colon inside plain (url) not separator unless followed by space
			}
		}
	}
	return -1
}

func isSeqLine(content string) bool {
	return content == "-" || strings.HasPrefix(content, "- ")
}

func (p *yParser) parseBlock(minIndent int) (*yNode, error) {
	p.skipBlank()
	if p.pos >= len(p.lines) {
		return nil, nil
	}
	line := p.lines[p.pos]
	if line.indent < minIndent {
		return nil, nil
	}
	if line.indent == 0 && isDocMarker(line.content) {
		return nil, nil
	}
	// sequence
	if isSeqLine(line.content) {
		return p.parseSeq(line.indent)
	}
	// mapping
	if findMapColon(line.content) >= 0 {
		return p.parseMap(line.indent)
	}
	// scalar (consume this line, plus more indented continuation lines)
	startLine := line.num
	text := strings.TrimSpace(line.content)
	p.pos++
	// Handle flow scalar spanning lines
	text, err := p.maybeAccumulateFlow(text, startLine)
	if err != nil {
		return nil, err
	}
	// plain scalar continuation
	if !strings.HasPrefix(text, "[") && !strings.HasPrefix(text, "{") && !strings.HasPrefix(text, "\"") && !strings.HasPrefix(text, "'") {
		for {
			save := p.pos
			p.skipBlank()
			if p.pos >= len(p.lines) {
				break
			}
			nl := p.lines[p.pos]
			if nl.indent > line.indent && findMapColon(nl.content) < 0 && !isSeqLine(nl.content) {
				text += " " + strings.TrimSpace(nl.content)
				p.pos++
			} else {
				p.pos = save
				break
			}
		}
	}
	node, err := parseScalarOrFlow(text, startLine)
	if err != nil {
		return nil, err
	}
	return node, nil
}

func (p *yParser) maybeAccumulateFlow(text string, startLine int) (string, error) {
	// count bracket depth outside quotes; if >0 consume following lines
	for {
		depth := flowDepth(text)
		if depth <= 0 {
			return text, nil
		}
		if p.pos >= len(p.lines) {
			// unclosed flow: return; parseFlow will error with appropriate message
			return text, nil
		}
		text += "\n" + p.lines[p.pos].content
		p.pos++
	}
}

func flowDepth(s string) int {
	inS, inD := false, false
	depth := 0
	for i := 0; i < len(s); i++ {
		c := s[i]
		if inS {
			if c == '\'' {
				if i+1 < len(s) && s[i+1] == '\'' {
					i++
				} else {
					inS = false
				}
			}
			continue
		}
		if inD {
			if c == '\\' {
				i++
				continue
			}
			if c == '"' {
				inD = false
			}
			continue
		}
		switch c {
		case '\'':
			inS = true
		case '"':
			inD = true
		case '[', '{':
			depth++
		case ']', '}':
			depth--
		}
	}
	return depth
}

func (p *yParser) parseSeq(indent int) (*yNode, error) {
	start := p.lines[p.pos].num
	node := &yNode{Kind: ySeq, Line: start}
	for {
		p.skipBlank()
		if p.pos >= len(p.lines) {
			break
		}
		line := p.lines[p.pos]
		if line.indent != indent || !isSeqLine(line.content) {
			break
		}
		// item content
		after := ""
		if len(line.content) > 1 {
			after = strings.TrimLeft(line.content[1:], " ")
		}
		if after == "" {
			p.pos++
			p.skipBlank()
			if p.pos < len(p.lines) && p.lines[p.pos].indent > indent {
				child, err := p.parseBlock(indent + 1)
				if err != nil {
					return nil, err
				}
				if child == nil {
					child = &yNode{Kind: yScalar, Line: line.num}
				}
				node.Items = append(node.Items, child)
			} else {
				node.Items = append(node.Items, &yNode{Kind: yScalar, Line: line.num})
			}
			continue
		}
		// transform current line into a virtual line with content after dash
		virtualIndent := indent + 2
		// compute actual column of 'after' within raw line: indent + 1(dash) + spaces
		rawAfterDash := ""
		if len(line.content) > 1 {
			rawAfterDash = line.content[1:]
		}
		spaces := 0
		for spaces < len(rawAfterDash) && rawAfterDash[spaces] == ' ' {
			spaces++
		}
		virtualIndent = indent + 1 + spaces
		p.lines[p.pos] = yLine{raw: line.raw, content: after, indent: virtualIndent, num: line.num, blank: false}
		child, err := p.parseBlock(virtualIndent)
		if err != nil {
			return nil, err
		}
		if child == nil {
			child = &yNode{Kind: yScalar, Line: line.num}
		}
		node.Items = append(node.Items, child)
	}
	return node, nil
}

func (p *yParser) parseMap(indent int) (*yNode, error) {
	start := p.lines[p.pos].num
	node := &yNode{Kind: yMap, Line: start}
	seen := map[string]int{}
	for {
		p.skipBlank()
		if p.pos >= len(p.lines) {
			break
		}
		line := p.lines[p.pos]
		if line.indent == 0 && isDocMarker(line.content) {
			break
		}
		if line.indent != indent {
			break
		}
		colon := findMapColon(line.content)
		if colon < 0 {
			break
		}
		keyText := strings.TrimSpace(line.content[:colon])
		keyNode, err := parseScalarOrFlow(keyText, line.num)
		if err != nil {
			return nil, err
		}
		keyStr := ""
		if keyNode != nil && keyNode.Kind == yScalar {
			keyStr, _ = scalarAsString(keyNode)
		} else {
			keyStr = keyText
		}
		if prev, ok := seen[keyStr]; ok && p.dupErr == nil {
			p.dupErr = yamlTypeErr(line.num, fmt.Sprintf("mapping key %q already defined at line %d", keyStr, prev))
		} else {
			seen[keyStr] = line.num
		}
		rest := strings.TrimLeft(line.content[colon+1:], " \t")
		pair := yPair{Key: keyStr, KeyLine: line.num, KeyNode: keyNode}
		p.pos++
		if rest != "" {
			// block scalar?
			if rest == "|" || rest == ">" || strings.HasPrefix(rest, "|") || strings.HasPrefix(rest, ">") {
				// ensure it is just an indicator (possibly +- and digits)
				ind := strings.Trim(rest, "+-0123456789")
				if ind == "|" || ind == ">" {
					val, err := p.parseBlockScalar(indent, rest)
					if err != nil {
						return nil, err
					}
					pair.Value = val
					node.Pairs = append(node.Pairs, pair)
					continue
				}
			}
			rest2, err := p.maybeAccumulateFlow(rest, line.num)
			if err != nil {
				return nil, err
			}
			val, err := parseScalarOrFlow(rest2, line.num)
			if err != nil {
				return nil, err
			}
			pair.Value = val
			node.Pairs = append(node.Pairs, pair)
			continue
		}
		// empty value: nested block or null
		save := p.pos
		p.skipBlank()
		if p.pos < len(p.lines) {
			nl := p.lines[p.pos]
			if nl.indent > indent {
				child, err := p.parseBlock(indent + 1)
				if err != nil {
					return nil, err
				}
				if child == nil {
					child = &yNode{Kind: yScalar, Line: line.num}
				}
				pair.Value = child
				node.Pairs = append(node.Pairs, pair)
				continue
			}
			if nl.indent == indent && isSeqLine(nl.content) {
				child, err := p.parseSeq(indent)
				if err != nil {
					return nil, err
				}
				pair.Value = child
				node.Pairs = append(node.Pairs, pair)
				continue
			}
		}
		p.pos = save
		pair.Value = &yNode{Kind: yScalar, Line: line.num}
		node.Pairs = append(node.Pairs, pair)
	}
	return node, nil
}

func (p *yParser) parseBlockScalar(parentIndent int, indicator string) (*yNode, error) {
	style := indicator[0]
	chomp := byte(0)
	if strings.Contains(indicator, "-") {
		chomp = '-'
	} else if strings.Contains(indicator, "+") {
		chomp = '+'
	}
	var rawLines []string
	blockIndent := -1
	startLine := 0
	for p.pos < len(p.lines) {
		l := p.lines[p.pos]
		if strings.TrimSpace(l.raw) == "" {
			rawLines = append(rawLines, "")
			p.pos++
			continue
		}
		if l.indent <= parentIndent {
			break
		}
		if blockIndent < 0 {
			blockIndent = l.indent
			startLine = l.num
		}
		trim := blockIndent
		if trim > len(l.raw) {
			trim = len(l.raw)
		}
		rawLines = append(rawLines, l.raw[trim:])
		p.pos++
	}
	if startLine == 0 && len(rawLines) > 0 {
		startLine = p.pos
	}
	// drop trailing blank lines collected beyond block? They are part of scalar depending chomp; simplify
	var text string
	if style == '>' {
		// fold single newlines to spaces, blank lines to newline
		var sb strings.Builder
		for i, ln := range rawLines {
			if i > 0 {
				if ln == "" || rawLines[i-1] == "" {
					sb.WriteString("\n")
				} else {
					sb.WriteString(" ")
				}
			}
			sb.WriteString(ln)
		}
		text = sb.String()
	} else {
		text = strings.Join(rawLines, "\n")
	}
	switch chomp {
	case '-':
		text = strings.TrimRight(text, "\n")
	case '+':
		if !strings.HasSuffix(text, "\n") {
			text += "\n"
		}
	default:
		text = strings.TrimRight(text, "\n")
		if len(rawLines) > 0 {
			text += "\n"
		}
	}
	return &yNode{Kind: yScalar, Value: text, Raw: text, Style: style, Line: startLine}, nil
}

// flow parsing
type flowParser struct {
	s    string
	pos  int
	line int
}

func parseScalarOrFlow(text string, line int) (*yNode, error) {
	text = strings.TrimSpace(text)
	if text == "" {
		return &yNode{Kind: yScalar, Line: line}, nil
	}
	if strings.HasPrefix(text, "[") || strings.HasPrefix(text, "{") {
		fp := &flowParser{s: text, line: line}
		n, err := fp.parseValue()
		if err != nil {
			return nil, err
		}
		fp.skipWS()
		// trailing junk ignored approximately
		return n, nil
	}
	if strings.HasPrefix(text, "'") {
		v, consumed, err := parseSingleQuoted(text)
		_ = consumed
		if err != nil {
			return nil, yamlSyntaxErr(line, "found unexpected end of stream")
		}
		return &yNode{Kind: yScalar, Value: v, Raw: text, Style: '\'', Line: line}, nil
	}
	if strings.HasPrefix(text, "\"") {
		v, consumed, err := parseDoubleQuoted(text)
		_ = consumed
		if err != nil {
			return nil, yamlSyntaxErr(line, "found unexpected end of stream")
		}
		return &yNode{Kind: yScalar, Value: v, Raw: text, Style: '"', Line: line}, nil
	}
	// anchors/tags: skip leading &anchor, *alias, !tag approximately
	if strings.HasPrefix(text, "&") {
		parts := strings.SplitN(text, " ", 2)
		if len(parts) == 2 {
			return parseScalarOrFlow(parts[1], line)
		}
	}
	if strings.HasPrefix(text, "!") {
		parts := strings.SplitN(text, " ", 2)
		if len(parts) == 2 {
			return parseScalarOrFlow(parts[1], line)
		}
	}
	return &yNode{Kind: yScalar, Value: text, Raw: text, Line: line}, nil
}

func (fp *flowParser) skipWS() {
	for fp.pos < len(fp.s) && (fp.s[fp.pos] == ' ' || fp.s[fp.pos] == '\t' || fp.s[fp.pos] == '\n' || fp.s[fp.pos] == '\r') {
		fp.pos++
	}
}

func (fp *flowParser) parseValue() (*yNode, error) {
	fp.skipWS()
	if fp.pos >= len(fp.s) {
		return &yNode{Kind: yScalar, Line: fp.line}, nil
	}
	switch fp.s[fp.pos] {
	case '[':
		return fp.parseSeq()
	case '{':
		return fp.parseMap()
	case '\'':
		v, n, err := parseSingleQuoted(fp.s[fp.pos:])
		if err != nil {
			return nil, yamlSyntaxErr(fp.line, "found unexpected end of stream")
		}
		fp.pos += n
		return &yNode{Kind: yScalar, Value: v, Raw: v, Style: '\'', Line: fp.line}, nil
	case '"':
		v, n, err := parseDoubleQuoted(fp.s[fp.pos:])
		if err != nil {
			return nil, yamlSyntaxErr(fp.line, "found unexpected end of stream")
		}
		fp.pos += n
		return &yNode{Kind: yScalar, Value: v, Raw: v, Style: '"', Line: fp.line}, nil
	default:
		start := fp.pos
		// plain scalar until , ] } or : followed by space/,]} (for map key detection caller may re-check)
		for fp.pos < len(fp.s) {
			c := fp.s[fp.pos]
			if c == ',' || c == ']' || c == '}' {
				break
			}
			if c == ':' {
				// lookahead
				if fp.pos+1 >= len(fp.s) || strings.ContainsRune(" \t,]}", rune(fp.s[fp.pos+1])) {
					break
				}
			}
			fp.pos++
		}
		raw := strings.TrimSpace(fp.s[start:fp.pos])
		return &yNode{Kind: yScalar, Value: raw, Raw: raw, Line: fp.line}, nil
	}
}

func (fp *flowParser) parseSeq() (*yNode, error) {
	node := &yNode{Kind: ySeq, Line: fp.line}
	fp.pos++ // [
	fp.skipWS()
	if fp.pos < len(fp.s) && fp.s[fp.pos] == ']' {
		fp.pos++
		return node, nil
	}
	for {
		if fp.pos >= len(fp.s) {
			return nil, yamlSyntaxErr(fp.line, "did not find expected ',' or ']'")
		}
		// check for single-pair flow mapping element like [k: v]
		save := fp.pos
		elem, err := fp.parseValue()
		if err != nil {
			return nil, err
		}
		fp.skipWS()
		if fp.pos < len(fp.s) && fp.s[fp.pos] == ':' {
			// it's a map key
			fp.pos++
			val, err := fp.parseValue()
			if err != nil {
				return nil, err
			}
			m := &yNode{Kind: yMap, Line: fp.line}
			keyStr, _ := scalarAsString(elem)
			m.Pairs = append(m.Pairs, yPair{Key: keyStr, KeyLine: fp.line, KeyNode: elem, Value: val})
			elem = m
			_ = save
		}
		node.Items = append(node.Items, elem)
		fp.skipWS()
		if fp.pos >= len(fp.s) {
			return nil, yamlSyntaxErr(fp.line, "did not find expected ',' or ']'")
		}
		if fp.s[fp.pos] == ']' {
			fp.pos++
			return node, nil
		}
		if fp.s[fp.pos] == ',' {
			fp.pos++
			fp.skipWS()
			// trailing comma
			if fp.pos < len(fp.s) && fp.s[fp.pos] == ']' {
				fp.pos++
				return node, nil
			}
			continue
		}
		return nil, yamlSyntaxErr(fp.line, "did not find expected ',' or ']'")
	}
}

func (fp *flowParser) parseMap() (*yNode, error) {
	node := &yNode{Kind: yMap, Line: fp.line}
	fp.pos++ // {
	fp.skipWS()
	if fp.pos < len(fp.s) && fp.s[fp.pos] == '}' {
		fp.pos++
		return node, nil
	}
	for {
		if fp.pos >= len(fp.s) {
			return nil, yamlSyntaxErr(fp.line, "did not find expected ',' or '}'")
		}
		key, err := fp.parseValue()
		if err != nil {
			return nil, err
		}
		fp.skipWS()
		var val *yNode
		if fp.pos < len(fp.s) && fp.s[fp.pos] == ':' {
			fp.pos++
			v, err := fp.parseValue()
			if err != nil {
				return nil, err
			}
			val = v
		} else {
			val = &yNode{Kind: yScalar, Line: fp.line}
		}
		keyStr, _ := scalarAsString(key)
		node.Pairs = append(node.Pairs, yPair{Key: keyStr, KeyLine: fp.line, KeyNode: key, Value: val})
		fp.skipWS()
		if fp.pos >= len(fp.s) {
			return nil, yamlSyntaxErr(fp.line, "did not find expected ',' or '}'")
		}
		if fp.s[fp.pos] == '}' {
			fp.pos++
			return node, nil
		}
		if fp.s[fp.pos] == ',' {
			fp.pos++
			continue
		}
		return nil, yamlSyntaxErr(fp.line, "did not find expected ',' or '}'")
	}
}

func parseSingleQuoted(s string) (string, int, error) {
	if len(s) == 0 || s[0] != '\'' {
		return "", 0, fmt.Errorf("not single quoted")
	}
	var sb strings.Builder
	i := 1
	for i < len(s) {
		if s[i] == '\'' {
			if i+1 < len(s) && s[i+1] == '\'' {
				sb.WriteByte('\'')
				i += 2
				continue
			}
			return sb.String(), i + 1, nil
		}
		sb.WriteByte(s[i])
		i++
	}
	return "", 0, fmt.Errorf("unterminated")
}

func parseDoubleQuoted(s string) (string, int, error) {
	if len(s) == 0 || s[0] != '"' {
		return "", 0, fmt.Errorf("not double quoted")
	}
	var sb strings.Builder
	i := 1
	for i < len(s) {
		c := s[i]
		if c == '"' {
			return sb.String(), i + 1, nil
		}
		if c == '\\' && i+1 < len(s) {
			n := s[i+1]
			switch n {
			case 'n':
				sb.WriteByte('\n')
				i += 2
			case 'r':
				sb.WriteByte('\r')
				i += 2
			case 't':
				sb.WriteByte('\t')
				i += 2
			case '\\':
				sb.WriteByte('\\')
				i += 2
			case '"':
				sb.WriteByte('"')
				i += 2
			case '/':
				sb.WriteByte('/')
				i += 2
			case 'b':
				sb.WriteByte('\b')
				i += 2
			case 'f':
				sb.WriteByte('\f')
				i += 2
			case 'v':
				sb.WriteByte('\v')
				i += 2
			case 'a':
				sb.WriteByte('\a')
				i += 2
			case 'e':
				sb.WriteByte(0x1b)
				i += 2
			case '0':
				sb.WriteByte(0)
				i += 2
			case 'x':
				if i+3 < len(s) {
					if v, err := strconv.ParseInt(s[i+2:i+4], 16, 32); err == nil {
						sb.WriteByte(byte(v))
						i += 4
					} else {
						i += 2
					}
				} else {
					i += 2
				}
			case 'u':
				if i+5 < len(s) {
					if v, err := strconv.ParseInt(s[i+2:i+6], 16, 32); err == nil {
						sb.WriteRune(rune(v))
						i += 6
					} else {
						i += 2
					}
				} else {
					i += 2
				}
			case 'U':
				if i+9 < len(s) {
					if v, err := strconv.ParseInt(s[i+2:i+10], 16, 32); err == nil {
						sb.WriteRune(rune(v))
						i += 10
					} else {
						i += 2
					}
				} else {
					i += 2
				}
			case '\n':
				// line continuation
				i += 2
				for i < len(s) && (s[i] == ' ' || s[i] == '\t') {
					i++
				}
			default:
				sb.WriteByte(n)
				i += 2
			}
			continue
		}
		// copy rune
		_, size := utf8.DecodeRuneInString(s[i:])
		sb.WriteString(s[i : i+size])
		i += size
	}
	return "", 0, fmt.Errorf("unterminated")
}

// --- scalar resolution / conversion ---

func isNullNode(n *yNode) bool {
	if n == nil {
		return true
	}
	if n.Kind != yScalar {
		return false
	}
	if n.Style != 0 {
		return false
	}
	switch n.Raw {
	case "", "~", "null", "Null", "NULL":
		return true
	}
	return false
}

func yamlBoolValue(raw string) (bool, bool) {
	switch raw {
	case "y", "Y", "yes", "Yes", "YES", "true", "True", "TRUE", "on", "On", "ON":
		return true, true
	case "n", "N", "no", "No", "NO", "false", "False", "FALSE", "off", "Off", "OFF":
		return false, true
	}
	return false, false
}

func yamlTagOf(n *yNode) string {
	if n == nil {
		return "!!null"
	}
	switch n.Kind {
	case ySeq:
		return "!!seq"
	case yMap:
		return "!!map"
	default:
		if n.Style != 0 {
			return "!!str"
		}
		if isNullNode(n) {
			return "!!null"
		}
		if _, ok := yamlBoolValue(n.Raw); ok {
			return "!!bool"
		}
		if _, ok := parseYAMLInt(n.Raw); ok {
			return "!!int"
		}
		if _, ok := parseYAMLFloat(n.Raw); ok {
			return "!!float"
		}
		return "!!str"
	}
}

func parseYAMLInt(raw string) (int64, bool) {
	s := strings.ReplaceAll(raw, "_", "")
	if s == "" {
		return 0, false
	}
	// hex, octal, binary
	neg := false
	t := s
	if strings.HasPrefix(t, "+") {
		t = t[1:]
	} else if strings.HasPrefix(t, "-") {
		neg = true
		t = t[1:]
	}
	var v int64
	var err error
	switch {
	case strings.HasPrefix(t, "0x") || strings.HasPrefix(t, "0X"):
		var uv uint64
		uv, err = strconv.ParseUint(t[2:], 16, 64)
		v = int64(uv)
	case strings.HasPrefix(t, "0o") || strings.HasPrefix(t, "0O"):
		var uv uint64
		uv, err = strconv.ParseUint(t[2:], 8, 64)
		v = int64(uv)
	case strings.HasPrefix(t, "0b") || strings.HasPrefix(t, "0B"):
		var uv uint64
		uv, err = strconv.ParseUint(t[2:], 2, 64)
		v = int64(uv)
	case len(t) > 1 && t[0] == '0' && allDigits(t):
		var uv uint64
		uv, err = strconv.ParseUint(t, 8, 64)
		if err != nil {
			// 08,09 are decimal in yaml 1.2? go-yaml may treat as int decimal? fallback decimal
			uv, err = strconv.ParseUint(t, 10, 64)
		}
		v = int64(uv)
	default:
		if !allDigits(t) {
			return 0, false
		}
		v, err = strconv.ParseInt(s, 10, 64)
		if err == nil {
			return v, true
		}
		return 0, false
	}
	if err != nil {
		return 0, false
	}
	if neg {
		v = -v
	}
	return v, true
}

func allDigits(s string) bool {
	if s == "" {
		return false
	}
	for _, c := range s {
		if c < '0' || c > '9' {
			return false
		}
	}
	return true
}

func parseYAMLFloat(raw string) (float64, bool) {
	switch raw {
	case ".inf", ".Inf", ".INF", "+.inf", "+.Inf", "+.INF":
		return strconvParseFloatInf(1), true
	case "-.inf", "-.Inf", "-.INF":
		return strconvParseFloatInf(-1), true
	case ".nan", ".Nan", ".NAN":
		// use a NaN via parse
		f, _ := strconv.ParseFloat("NaN", 64)
		return f, true
	}
	// must contain . or e and be numeric shape
	if !strings.ContainsAny(raw, ".eE") {
		return 0, false
	}
	f, err := strconv.ParseFloat(strings.ReplaceAll(raw, "_", ""), 64)
	if err != nil {
		return 0, false
	}
	// ensure raw is plausible numeric (no letters beyond e)
	for _, c := range raw {
		if !(c >= '0' && c <= '9' || c == '.' || c == 'e' || c == 'E' || c == '+' || c == '-' || c == '_') {
			return 0, false
		}
	}
	return f, true
}

func strconvParseFloatInf(sign int) float64 {
	f, _ := strconv.ParseFloat("+Inf", 64)
	if sign < 0 {
		f, _ = strconv.ParseFloat("-Inf", 64)
	}
	return f
}

func scalarAsString(n *yNode) (string, error) {
	if isNullNode(n) {
		return "", nil
	}
	if n.Kind != yScalar {
		return "", yamlTypeErr(n.Line, fmt.Sprintf("cannot unmarshal %s into string", yamlTagOf(n)))
	}
	if n.Style != 0 {
		return n.Value, nil
	}
	// plain: canonicalise resolved non-string scalars like go-yaml when decoding into string
	if b, ok := yamlBoolValue(n.Raw); ok {
		if b {
			return "true", nil
		}
		return "false", nil
	}
	if iv, ok := parseYAMLInt(n.Raw); ok {
		return strconv.FormatInt(iv, 10), nil
	}
	if fv, ok := parseYAMLFloat(n.Raw); ok {
		return strconv.FormatFloat(fv, 'g', -1, 64), nil
	}
	return n.Value, nil
}

func scalarAsBool(n *yNode) (bool, error) {
	if isNullNode(n) {
		return false, nil
	}
	if n.Kind != yScalar || n.Style != 0 {
		if n.Kind == yScalar {
			return false, yamlTypeErr(n.Line, fmt.Sprintf("cannot unmarshal %s `%s` into bool", yamlTagOf(n), n.Value))
		}
		return false, yamlTypeErr(n.Line, fmt.Sprintf("cannot unmarshal %s into bool", yamlTagOf(n)))
	}
	if b, ok := yamlBoolValue(n.Raw); ok {
		return b, nil
	}
	tag := yamlTagOf(n)
	return false, yamlTypeErr(n.Line, fmt.Sprintf("cannot unmarshal %s `%s` into bool", tag, n.Raw))
}

func nodeAsStringSlice(n *yNode) ([]string, error) {
	if isNullNode(n) {
		return nil, nil
	}
	if n.Kind != ySeq {
		if n.Kind == yScalar {
			return nil, yamlTypeErr(n.Line, fmt.Sprintf("cannot unmarshal %s `%s` into []string", yamlTagOf(n), n.Value))
		}
		return nil, yamlTypeErr(n.Line, fmt.Sprintf("cannot unmarshal %s into []string", yamlTagOf(n)))
	}
	out := []string{}
	for _, item := range n.Items {
		s, err := scalarAsString(item)
		if err != nil {
			return nil, err
		}
		out = append(out, s)
	}
	return out, nil
}

func mapGet(n *yNode, key string) *yNode {
	if n == nil || n.Kind != yMap {
		return nil
	}
	for _, p := range n.Pairs {
		if p.Key == key {
			return p.Value
		}
	}
	return nil
}
