		return nil, fmt.Errorf("could not unmarshal yaml: %w", yamlTypeErr(node.Line, fmt.Sprintf("cannot unmarshal %s into config.Config", yamlTagOf(node))))
	} else {
		// editor
		if n := mapGet(node, "editor"); n != nil {
			s, err := scalarAsString(n)
			if err != nil {
				return nil, fmt.Errorf("could not unmarshal yaml: %w", err)
			}
			cfg.Editor = s
		}
		if n := mapGet(node, "colorize"); n != nil {
			b, err := scalarAsBool(n)
			if err != nil {
				return nil, fmt.Errorf("could not unmarshal yaml: %w", err)
			}
			cfg.Colorize = b
		}
		if n := mapGet(node, "style"); n != nil {
			s, err := scalarAsString(n)
			if err != nil {
				return nil, fmt.Errorf("could not unmarshal yaml: %w", err)
			}
			cfg.Style = s
		}
		if n := mapGet(node, "formatter"); n != nil {
			s, err := scalarAsString(n)
			if err != nil {
				return nil, fmt.Errorf("could not unmarshal yaml: %w", err)
			}
			cfg.Formatter = s
		}
		if n := mapGet(node, "pager"); n != nil {
			s, err := scalarAsString(n)
			if err != nil {
				return nil, fmt.Errorf("could not unmarshal yaml: %w", err)
			}
			cfg.Pager = s
		}
		if n := mapGet(node, "cheatpaths"); n != nil {
			cps, err := nodeAsCheatpaths(n)
			if err != nil {
				return nil, fmt.Errorf("could not unmarshal yaml: %w", err)
			}
			cfg.Cheatpaths = cps
		}
	}

	// Process cheatpaths: expand ~, clean, skip nonexistent with warning.
	var processed []Cheatpath
	for _, cp := range cfg.Cheatpaths {
		if cp.nilItem {
			continue
		}
		expanded, err := expandTilde(cp.Path)
		if err != nil {
			return nil, fmt.Errorf("failed to expand ~: %w", err)
		}
		cleaned := filepath.Clean(expanded)
		cp.Path = cleaned
		if _, err := os.Stat(cleaned); err != nil {
			fmt.Fprintf(os.Stderr, "WARNING: cheatpath '%s' does not exist, skipping\n", cleaned)
			continue
		}
		processed = append(processed, cp)
	}
	cfg.Cheatpaths = processed

	// Editor resolution: VISUAL, then EDITOR override config value if non-empty
	if v := os.Getenv("VISUAL"); v != "" {
		cfg.Editor = v
	} else if v := os.Getenv("EDITOR"); v != "" {
		cfg.Editor = v
	}
	if cfg.Editor == "" {
		return nil, fmt.Errorf("no editor set")
	}

	// Validation: cheatpaths
	if len(cfg.Cheatpaths) == 0 {
		return nil, fmt.Errorf("config error: no cheatpaths specified")
	}
	seenNames := map[string]bool{}
	seenPaths := map[string]bool{}
	for _, cp := range cfg.Cheatpaths {
		if cp.Name == "" {
			return nil, fmt.Errorf("config error: cheatpath name cannot be empty")
		}
		if seenNames[cp.Name] {
			return nil, fmt.Errorf("config error: cheatpath name is not unique: %s", cp.Name)
		}
		seenNames[cp.Name] = true
		if seenPaths[cp.Path] {
			return nil, fmt.Errorf("config error: cheatpath path is not unique: %s", cp.Path)
		}
		seenPaths[cp.Path] = true
	}
	// formatter validation
	switch cfg.Formatter {
	case "", "terminal", "terminal256", "terminal16m":
	default:
		return nil, fmt.Errorf("config error: formatter is invalid: %s", cfg.Formatter)
	}

	// Append directory-scoped .cheat cheatpath (nearest ancestor)
	if cwdPath, ok := findLocalCheatPath(); ok {
		cfg.Cheatpaths = append(cfg.Cheatpaths, Cheatpath{Name: "cwd", Path: cwdPath, Tags: []string{}, Readonly: false})
	}

	return cfg, nil
}

func nodeAsCheatpaths(n *yNode) ([]Cheatpath, error) {
	if isNullNode(n) {
		return nil, nil
	}
	if n.Kind != ySeq {
		if n.Kind == yScalar {
			return nil, yamlTypeErr(n.Line, fmt.Sprintf("cannot unmarshal %s `%s` into []cheatpath.Path", yamlTagOf(n), n.Value))
		}
		return nil, yamlTypeErr(n.Line, fmt.Sprintf("cannot unmarshal %s into []cheatpath.Path", yamlTagOf(n)))
	}
	var out []Cheatpath
	for _, item := range n.Items {
		if isNullNode(item) {
			out = append(out, Cheatpath{nilItem: true})
			continue
		}
		if item.Kind != yMap {
			if item.Kind == yScalar {
				return nil, yamlTypeErr(item.Line, fmt.Sprintf("cannot unmarshal %s `%s` into cheatpath.Path", yamlTagOf(item), item.Value))
			}
			return nil, yamlTypeErr(item.Line, fmt.Sprintf("cannot unmarshal %s into cheatpath.Path", yamlTagOf(item)))
		}
		var cp Cheatpath
		if v := mapGet(item, "name"); v != nil {
			s, err := scalarAsString(v)
			if err != nil {
				return nil, err
			}
			cp.Name = s
		}
		if v := mapGet(item, "path"); v != nil {
			s, err := scalarAsString(v)
			if err != nil {
				return nil, err
			}
			cp.Path = s
		}
		if v := mapGet(item, "tags"); v != nil {
			ts, err := nodeAsStringSlice(v)
			if err != nil {
				return nil, err
			}
			cp.Tags = ts
		}
		if v := mapGet(item, "readonly"); v != nil {
			b, err := scalarAsBool(v)
			if err != nil {
				return nil, err
			}
			cp.Readonly = b
		}
		out = append(out, cp)
	}
	return out, nil
}

func findLocalCheatPath() (string, bool) {
	cwd, err := os.Getwd()
	if err != nil {
		return "", false
	}
	dir := cwd
	for {
		candidate := filepath.Join(dir, ".cheat")
		if info, err := os.Stat(candidate); err == nil && info.IsDir() {
			return candidate, true
		}
		parent := filepath.Dir(dir)
		if parent == dir {
			return "", false
		}
		dir = parent
	}
}

// loadConfig resolves and loads; if not found, returns a sentinel via found=false
func resolveConfig() (*Config, string, bool, error) {
	path, found, err := findConfig()
	if err != nil {
		return nil, "", false, err
	}
	if !found {
		return nil, path, false, nil
	}
	cfg, err := loadConfigFrom(path)
	if err != nil {
		return nil, path, true, err
	}
	return cfg, path, true, nil
}
GOEOF"}

