	if idx < 0 {
		return "", nil, "", fmt.Errorf("failed to delimit frontmatter")
	}
	yamlText := rest[:idx]
	body = rest[idx+len(delim):]
	node, perr := parseYAML(yamlText)
	if perr != nil {
		return "", nil, "", fmt.Errorf("failed to unmarshal frontmatter: %w", perr)
	}
	if node == nil || (node.Kind == yScalar && isNullNode(node)) {
		return "", nil, body, nil
	}
	if node.Kind != yMap {
		// approximate error
		if node.Kind == yScalar {
			return "", nil, "", fmt.Errorf("failed to unmarshal frontmatter: %w", yamlTypeErr(node.Line, fmt.Sprintf("cannot unmarshal %s `%s` into frontmatter.Frontmatter", yamlTagOf(node), node.Value)))
		}
		return "", nil, "", fmt.Errorf("failed to unmarshal frontmatter: %w", yamlTypeErr(node.Line, fmt.Sprintf("cannot unmarshal %s into frontmatter.Frontmatter", yamlTagOf(node))))
	}
	if n := mapGet(node, "syntax"); n != nil {
		s, serr := scalarAsString(n)
		if serr != nil {
			return "", nil, "", fmt.Errorf("failed to unmarshal frontmatter: %w", serr)
		}
		syntax = s
	}
	if n := mapGet(node, "tags"); n != nil {
		ts, serr := nodeAsStringSlice(n)
		if serr != nil {
			return "", nil, "", fmt.Errorf("failed to unmarshal frontmatter: %w", serr)
		}
		tags = ts
	}
	return syntax, tags, body, nil
}

func loadSheet(title, path string, cp Cheatpath) (Sheet, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		return Sheet{}, fmt.Errorf("failed to read file: %s, %w", path, err)
	}
	content := string(data)
	syntax, fmTags, body, err := parseFrontmatter(content)
	if err != nil {
		return Sheet{}, fmt.Errorf("failed to parse front-matter: %w", err)
	}
	// combine tags: cheatpath tags + frontmatter tags (order preserved here; sorted at display)
	tags := []string{}
