func loadSheets(cheatpaths []Cheatpath) ([]Sheet, error) {
	var sheets []Sheet
	for _, cp := range cheatpaths {
		err := filepath.Walk(cp.Path, func(path string, info os.FileInfo, walkErr error) error {
			if walkErr != nil {
				// mimic original: wrap as failed to load sheet if path known? Walk passes err for a path; return it and wrap below generically
				// Determine title approximately
				title := sheetTitle(cp.Path, path)
				return fmt.Errorf("failed to load sheet: %s, path: %s, err: %w", title, path, walkErr)
			}
