			}
			sheets = append(sheets, s)
			return nil
		})
		if err != nil {
			return nil, fmt.Errorf("failed to load cheatsheets: %w", err)
		}
	}
	return sheets, nil
}

func sheetTitle(base, path string) string {
	// Original appears to trim the cheatpath prefix (giving empty title when the cheatpath itself is a file)
	t := strings.TrimPrefix(path, base)
	t = strings.TrimPrefix(t, "/")
	// On the "." base case, Walk yields paths like "th/personal/alpha" (no ./ prefix), TrimPrefix "." would not match meaningfully;
	// strings.TrimPrefix above with base="." would strip a leading dot from e.g. ".hidden"?? Walk root "." yields "." then joins: ".hidden" as "hidden"? Actually filepath.Walk(".") gives paths: ".", "file" (Join cleans). For file "th/...", path doesn't start with "." so t stays correct.
	// But our TrimPrefix with base "." removed first char if path begins with '.' (root file ".cheat"?) Edge ignore.
	// If base is "." and path starts with "."+separator handled.
	if base == "." {
		// path from Walk(".") is already relative without leading ./
		return path
	}
	return t
}

func sortedTags(tags []string) []string {
	out := append([]string(nil), tags...)
	sort.Strings(out)
	return out
}

func filterByTag(sheets []Sheet, tag string) []Sheet {
	var out []Sheet
	for _, s := range sheets {
		for _, t := range s.Tags {
			if t == tag {
				out = append(out, s)
				break
			}
		}
	}
	return out
}

func filterCheatpathsByName(cps []Cheatpath, name string) []Cheatpath {
	var out []Cheatpath
	for _, cp := range cps {
		if cp.Name == name {
			out = append(out, cp)
		}
	}
	return out
}

func findSheet(sheets []Sheet, title string) (Sheet, bool) {
	// last matching sheet wins
	var found Sheet
	ok := false
	for _, s := range sheets {
		if s.Title == title {
			found = s
			ok = true
		}
	}
	return found, ok
}

func sheetsWithTitle(sheets []Sheet, title string) []Sheet {
	var out []Sheet
	for _, s := range sheets {
		if s.Title == title {
			out = append(out, s)
		}
	}
	return out
}
