	"unalias": true, "set": true, "unset": true, "shift": true, "test": true, "eval": true, "exec": true,
	"exit": true, "read": true, "local": true, "declare": true, "typeset": true, "let": true, "printf": true,
	"break": true, "continue": true, "trap": true, "umask": true, "wait": true, "jobs": true, "fg": true, "bg": true,
	"kill": true, "true": true, "false": true, "type": true, "hash": true, "help": true, "history": true,
}

var varRe = regexp.MustCompile(`^\$(\{[^}]*\}|[A-Za-z_][A-Za-z0-9_]*|[0-9@*#?$!_-])`)
var numRe = regexp.MustCompile(`^[0-9]+(\.[0-9]*)?`)

func isSpaceByte(c byte) bool { return c == ' ' || c == '\t' || c == '\r' }
func isWordByte(c byte) bool {
	return c >= 'a' && c <= 'z' || c >= 'A' && c <= 'Z' || c >= '0' && c <= '9' || c == '_'
}

func lexBash(text string) []ctoken {
	var toks []ctoken
	i := 0
	atWordStart := true // start of a word (for comment/number/keyword detection)
	for i < len(text) {
		c := text[i]
		if c == '\n' {
			toks = append(toks, ctoken{tText, "\n"})
			i++
			atWordStart = true
			continue
		}
		if c == '#' && atWordStart {
			j := i
			for j < len(text) && text[j] != '\n' {
				j++
			}
			toks = append(toks, ctoken{tComment, text[i:j]})
			i = j
			atWordStart = false
			continue
		}
		if isSpaceByte(c) {
			j := i
			for j < len(text) && isSpaceByte(text[j]) {
				j++
			}
			toks = append(toks, ctoken{tText, text[i:j]})
			i = j
			atWordStart = true
			continue
		}
		if c == '\'' {
			j := i + 1
			for j < len(text) && text[j] != '\'' && text[j] != '\n' {
				j++
			}
			if j < len(text) && text[j] == '\'' {
				j++
			}
			toks = append(toks, ctoken{tStringSingle, text[i:j]})
			i = j
			atWordStart = false
			continue
		}
		if c == '"' {
			// double-quoted with variable interpolation split
			j := i + 1
			start := i
			for j < len(text) && text[j] != '\n' {
				if text[j] == '\\' && j+1 < len(text) {
					j += 2
					continue
				}
				if text[j] == '$' {
					if m := varRe.FindString(text[j:]); m != "" {
						if j > start {
							toks = append(toks, ctoken{tStringDouble, text[start:j]})
						}
						toks = append(toks, ctoken{tNameVariable, m})
						j += len(m)
						start = j
						continue
					}
				}
				if text[j] == '"' {
					j++
					break
				}
				j++
			}
			if j > start {
				toks = append(toks, ctoken{tStringDouble, text[start:j]})
			}
			i = j
			atWordStart = false
			continue
		}
		if c == '`' {
			j := i + 1
			for j < len(text) && text[j] != '`' && text[j] != '\n' {
				j++
			}
			if j < len(text) && text[j] == '`' {
				j++
			}
			toks = append(toks, ctoken{tStringBacktick, text[i:j]})
			i = j
			atWordStart = false
			continue
		}
		if c == '$' {
			if m := varRe.FindString(text[i:]); m != "" {
				// $(...) and $((...)) handled coarsely: varRe won't match '('; special-case
				toks = append(toks, ctoken{tNameVariable, m})
				i += len(m)
				atWordStart = false
				continue
			}
			// fallthrough as text char
		}
		if atWordStart && c >= '0' && c <= '9' {
			if m := numRe.FindString(text[i:]); m != "" {
				end := i + len(m)
				// only a number token if not followed by word char or / or . (paths etc.)
				if end >= len(text) || (!isWordByte(text[end]) && text[end] != '/' && text[end] != '.') {
					toks = append(toks, ctoken{tNumber, m})
					i = end
					atWordStart = false
					continue
				}
			}
		}
		// operators / punctuation
		if strings.ContainsRune("|&;()<>", rune(c)) {
			// consume run of same-ish operator chars
			j := i
			for j < len(text) && strings.ContainsRune("|&;<>", rune(text[j])) {
				j++
			}
			if j == i { // parens single
				j = i + 1
				toks = append(toks, ctoken{tOperator, text[i:j]})
			} else {
				// pipe etc are Text-coloured separate tokens in chroma bash (Punctuation)
				toks = append(toks, ctoken{tPunctuation, text[i:j]})
			}
			i = j
			atWordStart = true
			continue
		}
		// word / other run: consume until space, quote, operator, newline, $ (variable), #
		j := i
		for j < len(text) {
			ch := text[j]
			if ch == '\n' || isSpaceByte(ch) || ch == '\'' || ch == '"' || ch == '`' || strings.ContainsRune("|&;()<>", rune(ch)) {
				break
			}
			if ch == '$' && j > i {
				break
			}
			if ch == '\\' && j+1 < len(text) && text[j+1] != '\n' {
				j += 2
				continue
			}
			j++
		}
		if j == i {
			j = i + 1
		}
		word := text[i:j]
		typ := tText
		if atWordStart {
			if bashKeywords[word] {
				typ = tKeyword
			} else if bashBuiltins[word] {
				typ = tNameBuiltin
			}
		}
		toks = append(toks, ctoken{typ, word})
		i = j
		atWordStart = false
	}
	return toks
}

// ---------- generic lexer ----------

type langConf struct {
	keywords     map[string]bool
	typeKeywords map[string]bool
	lineComment  string
	blockStart   string
	blockEnd     string
	jsNames      bool // identifiers get function-ish colour
}

func langConfig(lang string) langConf {
	kw := func(words string) map[string]bool {
		m := map[string]bool{}
		for _, w := range strings.Fields(words) {
			m[w] = true
		}
		return m
	}
	switch lang {
	case "python":
		return langConf{keywords: kw("def return if elif else for while import from as class pass break continue and or not in is None True False lambda with try except finally raise yield global nonlocal assert del async await print"), typeKeywords: kw(""), lineComment: "#"}
	case "javascript":
		return langConf{keywords: kw("const let var function return if else for while new class extends import from export default async await typeof of in void delete this true false null undefined switch case break continue try catch finally throw"), lineComment: "//", blockStart: "/*", blockEnd: "*/", jsNames: true}
	case "go":
		return langConf{keywords: kw("func var const type struct interface map chan go defer return if else for range switch case break continue select import"), typeKeywords: kw("string int int64 float64 bool byte rune error uint uintptr float32 int32 int16 int8 uint64 uint32"), lineComment: "//", blockStart: "/*", blockEnd: "*/"}
	case "c", "cpp", "java":
		return langConf{keywords: kw("if else for while return switch case break continue struct class public private protected static void new sizeof typedef enum union const volatile extern goto do"), typeKeywords: kw("int char long short float double unsigned signed bool void size_t"), lineComment: "//", blockStart: "/*", blockEnd: "*/"}
	case "ruby":
		return langConf{keywords: kw("def end if elsif else unless case when for while until do begin rescue ensure class module return yield self nil true false and or not in then"), lineComment: "#"}
	case "rust":
		return langConf{keywords: kw("fn let mut pub struct enum impl trait for in if else match return loop while break continue const static type where use mod crate self Self true false as ref move async await dyn unsafe"), lineComment: "//", blockStart: "/*", blockEnd: "*/"}
	case "yaml", "toml":
		return langConf{keywords: kw("true false null"), lineComment: "#"}
	case "sql":
		return langConf{keywords: kw("SELECT FROM WHERE INSERT INTO VALUES UPDATE DELETE CREATE TABLE DROP ALTER JOIN ON AND OR NOT NULL PRIMARY KEY select from where insert into values update delete create table"), lineComment: "--"}
	default:
		return langConf{keywords: kw(""), lineComment: "#"}
	}
}

func lexGeneric(text, lang string) []ctoken {
	cfg := langConfig(lang)
	var toks []ctoken
	i := 0
	prevSignificant := "" // previous identifier (for python def / go package/func name)
	for i < len(text) {
		c := text[i]
		if c == '\n' {
			toks = append(toks, ctoken{tText, "\n"})
			i++
			prevSignificant = ""
			continue
		}
		// line comment
		if cfg.lineComment != "" && strings.HasPrefix(text[i:], cfg.lineComment) {
			j := i
			for j < len(text) && text[j] != '\n' {
				j++
			}
			// Chroma JS/Go comment includes newline? Observed JS comment at EOL had no trailing empty text token; emulate by including newline in comment token for // languages, excluding for python/# (observed trailing empty)
			if cfg.lineComment == "//" && j < len(text) && text[j] == '\n' {
				toks = append(toks, ctoken{tComment, text[i:j+1]})
				i = j + 1
			} else {
				toks = append(toks, ctoken{tComment, text[i:j]})
				i = j
			}
			prevSignificant = ""
			continue
		}
		if cfg.blockStart != "" && strings.HasPrefix(text[i:], cfg.blockStart) {
			end := strings.Index(text[i+len(cfg.blockStart):], cfg.blockEnd)
			j := len(text)
			if end >= 0 {
				j = i + len(cfg.blockStart) + end + len(cfg.blockEnd)
			}
			toks = append(toks, ctoken{tComment, text[i:j]})
			i = j
			continue
		}
		if isSpaceByte(c) {
			j := i
			for j < len(text) && isSpaceByte(text[j]) {
				j++
			}
			toks = append(toks, ctoken{tText, text[i:j]})
			i = j
			continue
		}
		if c == '\'' || c == '"' || c == '`' {
			quote := c
			j := i + 1
			for j < len(text) {
				if text[j] == '\\' && quote != '\'' {
					j += 2
					continue
				}
				if text[j] == '\n' && quote != '`' {
					break
				}
				if text[j] == quote {
					j++
					break
				}
				j++
			}
			toks = append(toks, ctoken{tString, text[i:j]})
			i = j
			prevSignificant = ""
			continue
		}
		if c >= '0' && c <= '9' {
			j := i
			for j < len(text) && (isWordByte(text[j]) || text[j] == '.') {
				j++
			}
			toks = append(toks, ctoken{tNumber, text[i:j]})
			i = j
			prevSignificant = ""
			continue
		}
		if isWordByte(c) && !(c >= '0' && c <= '9') {
			j := i
			for j < len(text) && (isWordByte(text[j]) || text[j] == '$') {
				j++
			}
			word := text[i:j]
			typ := tName
			if cfg.jsNames {
				typ = tNameFunction
			}
			if cfg.keywords[word] {
				typ = tKeyword
				if word == "package" && lang == "go" {
					typ = tKeywordNamespace
				}
			} else if cfg.typeKeywords != nil && cfg.typeKeywords[word] {
				typ = tKeywordType
			} else if prevSignificant == "def" || prevSignificant == "func" || prevSignificant == "class" {
				typ = tNameFunction
			} else if prevSignificant == "package" {
				typ = tNameNamespace
			} else {
				// function call: identifier followed by '(' -> function in many chroma lexers (go/python name before () remains Name in python? observed python foo def name handled; plain calls - keep for go/js/c)
				k := j
				for k < len(text) && text[k] == ' ' {
					k++
				}
				// only immediate '(' without space for calls (python chroma does NOT colour call names as function generally; skip for python)
				if lang != "python" && k == j && k < len(text) && text[k] == '(' {
					typ = tNameFunction
				}
			}
			toks = append(toks, ctoken{typ, word})
			prevSignificant = word
			i = j
			continue
		}
		// operator / punctuation single or run
		if strings.ContainsRune("+-*/%=<>!&|^~", rune(c)) {
			// handle => as punctuation in JS (observed text-coloured and coalesced with spaces differently) - emit as punctuation
			if strings.HasPrefix(text[i:], "=>") {
				toks = append(toks, ctoken{tPunctuation, "=>"})
				i += 2
				prevSignificant = ""
				continue
			}
			j := i
			for j < len(text) && strings.ContainsRune("+-*/%=<>!&|^~", rune(text[j])) {
				j++
			}
			toks = append(toks, ctoken{tOperator, text[i:j]})
			i = j
			prevSignificant = ""
			continue
		}
		// punctuation run
		j := i
		for j < len(text) && strings.ContainsRune("([{)]},:;.", rune(text[j])) {
			j++
		}
		if j == i {
			j = i + 1
		}
		toks = append(toks, ctoken{tPunctuation, text[i:j]})
		i = j
		// keep prevSignificant for def foo() colon etc? reset after punctuation mostly but def->name handled before
		if prevSignificant != "def" {
			// do not reset immediately in cases like "package" handled; punctuation ends name contexts
			prevSignificant = ""
		}
	}
	return toks
}
GOEOF"}

