    cheat -c -r -s '(?:[0-9]{1,3}\.){3}[0-9]{1,3}'

  To remove (delete) the foo/bar cheatsheet:
    cheat --rm foo/bar

  To update all git-backed cheatpaths:
    cheat --update

  To view the configuration file path:
    cheat --conf

  To generate shell completions (bash, zsh, fish, powershell):
    cheat --completion bash

Flags:
  -a, --all                Search among all cheatpaths
  -b, --brief              List cheatsheets without file paths
  -c, --colorize           Colorize output
      --completion shell   Generate shell completion script (shell: bash, zsh, fish, powershell)
      --conf               Display the config file path
  -d, --directories        List cheatsheet directories
  -e, --edit cheatsheet    Edit cheatsheet
  -h, --help               help for cheat
      --init               Write a default config file to stdout
  -l, --list               List cheatsheets
  -p, --path name          Return only sheets found on cheatpath name
  -r, --regex              Treat search <phrase> as a regex
      --rm cheatsheet      Remove (delete) cheatsheet
  -s, --search phrase      Search cheatsheets for phrase
  -t, --tag tag            Return only sheets matching tag
  -T, --tags               List all tags in use
  -u, --update             Update git-backed cheatpaths
  -v, --version            Print the version number
`

//go:embed assets/completion-bash.txt
var completionBash string

//go:embed assets/completion-zsh.txt
var completionZsh string

//go:embed assets/completion-fish.txt
var completionFish string

//go:embed assets/completion-powershell.txt
var completionPowershell string

type exitError struct {
	code   int
	msg    string
	silent bool
}

func (e *exitError) Error() string {
	if e == nil {
		return ""
	}
	return e.msg
}

func errExit(code int, msg string) error { return &exitError{code: code, msg: msg} }
func errExitSilent(code int) error      { return &exitError{code: code, silent: true} }

func main() {
	code := run(os.Args[1:])
	os.Exit(code)
}

// -------- flags --------

type flagDef struct {
	long  string
	short string // one rune string or ""
	isBool bool
	usage string // raw usage incl backticks
}

var flagDefs []flagDef

func init() {
	// alphabetical by long (helps completion ordering)
	flagDefs = []flagDef{
		{"all", "a", true, "Search among all cheatpaths"},
		{"brief", "b", true, "List cheatsheets without file paths"},
		{"colorize", "c", true, "Colorize output"},
		{"completion", "", false, "Generate shell completion script (`shell`: bash, zsh, fish, powershell)"},
		{"conf", "", true, "Display the config file path"},
		{"directories", "d", true, "List cheatsheet directories"},
		{"edit", "e", false, "Edit `cheatsheet`"},
		{"help", "h", true, "help for cheat"},
		{"init", "", true, "Write a default config file to stdout"},
		{"list", "l", true, "List cheatsheets"},
		{"path", "p", false, "Return only sheets found on cheatpath `name`"},
		{"regex", "r", true, "Treat search <phrase> as a regex"},
		{"rm", "", false, "Remove (delete) `cheatsheet`"},
		{"search", "s", false, "Search cheatsheets for `phrase`"},
		{"tag", "t", false, "Return only sheets matching `tag`"},
		{"tags", "T", true, "List all tags in use"},
		{"update", "u", true, "Update git-backed cheatpaths"},
		{"version", "v", true, "Print the version number"},
	}
}

func flagByLong(name string) *flagDef {
	for i := range flagDefs {
		if flagDefs[i].long == name {
			return &flagDefs[i]
		}
	}
	return nil
}
func flagByShort(r rune) *flagDef {
	for i := range flagDefs {
		if flagDefs[i].short != "" {
			sr, _ := utf8.DecodeRuneInString(flagDefs[i].short)
			if sr == r {
				return &flagDefs[i]
			}
		}
	}
	return nil
}

type options struct {
	bools   map[string]bool
	strs    map[string]string
	changed map[string]bool
	args    []string
}

func newOptions() *options {
	return &options{bools: map[string]bool{}, strs: map[string]string{}, changed: map[string]bool{}}
}
func (o *options) b(name string) bool { return o.bools[name] }
func (o *options) s(name string) string { return o.strs[name] }
func (o *options) changedFlag(name string) bool { return o.changed[name] }

func boolFlagDisplayName(def *flagDef) string {
	if def.short != "" {
		return fmt.Sprintf("-%s, --%s", def.short, def.long)
	}
	return fmt.Sprintf("--%s", def.long)
}

func parseBoolValue(def *flagDef, val string) (bool, error) {
	bv, err := strconv.ParseBool(val)
	if err != nil {
		return false, fmt.Errorf("invalid argument %q for %q flag: %v", val, boolFlagDisplayName(def), err)
	}
	return bv, nil
}

// parseFlags parses like pflag with interspersed args. Returns opts, help bool, error.
func parseFlags(argv []string) (*options, error) {
	o := newOptions()
	i := 0
	terminated := false
	for i < len(argv) {
		arg := argv[i]
		i++
		if terminated {
			o.args = append(o.args, arg)
			continue
		}
		if arg == "--" {
			terminated = true
			continue
		}
		if len(arg) < 2 || arg[0] != '-' {
			o.args = append(o.args, arg)
			continue
		}
		if arg[1] == '-' {
			// long
			s := arg[2:]
			if len(s) == 0 || s[0] == '-' || s[0] == '=' {
				return nil, fmt.Errorf("bad flag syntax: %s", arg)
			}
			name := s
			value := ""
			hasValue := false
			if eq := strings.Index(s, "="); eq >= 0 {
				name = s[:eq]
				value = s[eq+1:]
				hasValue = true
			}
			def := flagByLong(name)
			if def == nil {
				return nil, fmt.Errorf("unknown flag: --%s", name)
			}
			o.changed[def.long] = true
			if def.isBool {
				if hasValue {
					bv, err := parseBoolValue(def, value)
					if err != nil {
						return nil, err
					}
					o.bools[def.long] = bv
				} else {
					o.bools[def.long] = true
				}
			} else {
				if hasValue {
					o.strs[def.long] = value
				} else {
					if i >= len(argv) {
						return nil, fmt.Errorf("flag needs an argument: --%s", name)
					}
					o.strs[def.long] = argv[i]
					i++
				}
			}
			continue
		}
		// shorthand
		s := arg[1:]
		for len(s) > 0 {
			r, size := utf8.DecodeRuneInString(s)
			def := flagByShort(r)
			if def == nil {
				return nil, fmt.Errorf("unknown shorthand flag: %q in -%s", r, s)
			}
			o.changed[def.long] = true
			rest := s[size:]
			if def.isBool {
				if len(rest) > 0 && rest[0] == '=' {
					val := rest[1:]
					bv, err := parseBoolValue(def, val)
					if err != nil {
						return nil, err
					}
					o.bools[def.long] = bv
					s = ""
				} else {
					o.bools[def.long] = true
					s = rest
				}
			} else {
				if len(rest) > 0 {
					if rest[0] == '=' {
						o.strs[def.long] = rest[1:]
					} else {
						o.strs[def.long] = rest
					}
					s = ""
				} else {
					if i >= len(argv) {
						return nil, fmt.Errorf("flag needs an argument: %q in -%s", r, s)
					}
					o.strs[def.long] = argv[i]
					i++
					s = ""
				}
			}
		}
	}
	return o, nil
}

// -------- stdin prompt shared reader --------
var stdinReader = bufio.NewReader(os.Stdin)

func promptYesNo() (bool, error) {
	line, err := stdinReader.ReadString('\n')
	if err != nil && len(line) == 0 {
		return false, err
	}
	answer := strings.ToLower(strings.TrimSpace(line))
	return answer == "" || answer == "y", nil
}

// -------- run --------

func run(argv []string) int {
	// Cobra-generated completion helper commands
	if len(argv) > 0 && (argv[0] == "__complete" || argv[0] == "__completeNoDesc") {
		return runComplete(argv[0] == "__completeNoDesc", argv[1:])
	}

	opts, err := parseFlags(argv)
	if err != nil {
		fmt.Fprintln(os.Stderr, err.Error())
		return 1
	}
	if opts.b("help") {
		fmt.Print(helpText)
		return 0
	}
	if len(opts.args) > 1 {
		fmt.Fprintf(os.Stderr, "accepts at most 1 arg(s), received %d\n", len(opts.args))
		return 1
	}

	// Early modes that bypass config (in observed priority): init > version > completion
	if opts.b("init") {
		if err := doInit(); err != nil {
			return handleErr(err)
		}
		return 0
	}
	if opts.b("version") {
		fmt.Println(version)
		return 0
	}
	if opts.changedFlag("completion") {
		if err := doCompletion(opts.s("completion")); err != nil {
			return handleErr(err)
		}
		return 0
	}

	// Resolve config; installer if missing
	cfg, cfgPath, found, err := resolveConfig()
	if err != nil {
		// resolveConfig returns expand errors already as "failed to expand ~: ..."
		fmt.Fprintf(os.Stderr, "failed to load config: %v\n", err)
		return 1
	}
	if !found {
		// installer flow
		if err := runInstallerFlow(cfgPath); err != nil {
			return handleErr(err)
		}
		return 0
	}
	// resolveConfig already loaded? it returns cfg when found; note load errors inside resolveConfig come back as err with .. we wrapped above as failed to load config
	// But resolveConfig's load errors are returned via err and cfg nil. Above handles.
	if cfg == nil {
		// Should not happen
		return 1
	}

	// --path validation (before conf etc.)
	if opts.changedFlag("path") {
		pname := opts.s("path")
		exists := false
		for _, cp := range cfg.Cheatpaths {
			if cp.Name == pname {
				exists = true
				break
			}
		}
		if !exists {
			fmt.Fprintf(os.Stderr, "invalid option --path: cheatpath does not exist: %s\n", pname)
			return 1
		}
	}

	// conf
	if opts.b("conf") {
		fmt.Println(cfg.Path)
		return 0
	}

	// directories
	if opts.b("directories") {
		return handleErr(doDirectories(cfg, opts))
	}

	// cheatpaths filtered by --path (used for sheet loading & edit destinations & update)
	pathFiltered := cfg.Cheatpaths
	if opts.changedFlag("path") {
		pathFiltered = filterCheatpathsByName(cfg.Cheatpaths, opts.s("path"))
	}

	// edit
	if opts.changedFlag("edit") {
		return handleErr(doEdit(cfg, opts, pathFiltered))
	}

	// list / brief
	if opts.b("list") || opts.b("brief") {
		return handleErr(doList(cfg, opts, pathFiltered, opts.b("brief")))
	}

	// tags
	if opts.b("tags") {
		return handleErr(doTags(cfg, opts, pathFiltered))
	}

	// update
	if opts.b("update") {
		return handleErr(doUpdate(cfg, opts, pathFiltered))
	}

	// search
	if opts.changedFlag("search") {
		return handleErr(doSearch(cfg, opts, pathFiltered))
	}

	// rm
	if opts.changedFlag("rm") {
		return handleErr(doRm(cfg, opts, pathFiltered))
	}

	// positional display / all
	if len(opts.args) == 1 {
		if opts.b("all") {
			return handleErr(doDisplayAll(cfg, opts, pathFiltered))
		}
		return handleErr(doDisplay(cfg, opts, pathFiltered))
	}

	// no arg: if tag was specified, list (observed)
	if opts.changedFlag("tag") {
		return handleErr(doList(cfg, opts, pathFiltered, false))
	}

	fmt.Print(helpText)
	return 0
}

func handleErr(err error) int {
	if err == nil {
		return 0
	}
	if ee, ok := err.(*exitError); ok {
		if !ee.silent && ee.msg != "" {
			fmt.Fprintln(os.Stderr, ee.msg)
		}
		return ee.code
	}
	fmt.Fprintln(os.Stderr, err.Error())
	return 1
}

func runInstallerFlow(cfgPath string) error {
	fmt.Print("A config file was not found. Would you like to create one now? [Y/n]: ")
	yes, err := promptYesNo()
	if err != nil {
		return errExit(1, fmt.Sprintf("failed to create config: failed to prompt: %v", err))
	}
	if !yes {
		return nil
	}
	if err := runInstaller(cfgPath); err != nil {
		return errExit(1, fmt.Sprintf("failed to run installer: %v", err))
	}
	return nil
}

func runInstaller(cfgPath string) error {
	fmt.Print("Would you like to download the community cheatsheets? [Y/n]: ")
	download, err := installerPrompt()
	if err != nil {
		return fmt.Errorf("failed to prompt: %w", err)
	}
	configDir := filepath.Dir(cfgPath)
	sheetsRoot := filepath.Join(configDir, "cheatsheets")
	if download {
		communityPath := filepath.Join(sheetsRoot, "community")
		if err := os.MkdirAll(sheetsRoot, 0o755); err != nil {
			return fmt.Errorf("failed to create cheatsheets directory: %w", err)
		}
		fmt.Printf("Cloning community cheatsheets to %s.\n", communityPath)
		if err := cloneCommunity(communityPath); err != nil {
			return fmt.Errorf("failed to clone cheatsheets: %w", err)
		}
	}
	// create personal/work dirs
	for _, name := range []string{"personal", "work"} {
		if err := os.MkdirAll(filepath.Join(sheetsRoot, name), 0o755); err != nil {
			return fmt.Errorf("failed to create directory: %w", err)
		}
	}
	// write config file
	tmpl, err := generateConfig(cfgPath)
	if err != nil {
		return err
	}
	if err := createConfigFile(cfgPath, tmpl); err != nil {
		return fmt.Errorf("failed to create config file: %w", err)
	}
	fmt.Printf("Created config file: %s\n", cfgPath)
	fmt.Println("Please read this file for advanced configuration information.")
	return nil
}

func installerPrompt() (bool, error) {
	yes, err := promptYesNo()
	if err != nil {
		return false, fmt.Errorf("failed to prompt: %w", err)
	}
	return yes, nil
}

func createConfigFile(path, content string) error {
	dir := filepath.Dir(path)
	if err := os.MkdirAll(dir, 0o755); err != nil {
		return fmt.Errorf("failed to create file: %w", err)
	}
	f, err := os.Create(path)
	if err != nil {
		return fmt.Errorf("failed to create file: %w", err)
	}
	defer f.Close()
	if _, err := f.WriteString(content); err != nil {
		return fmt.Errorf("failed to create file: %w", err)
	}
	return nil
}

func cloneCommunity(dest string) error {
	// Probe the smart-HTTP endpoint first so that, offline, the error text
	// resembles the reference (which reports the go-git HTTP error).
	url := "https://github.com/cheat/cheatsheets.git/info/refs?service=git-upload-pack"
	client := &http.Client{Timeout: 30 * time.Second}
	resp, err := client.Get(url)
	if err != nil {
		return fmt.Errorf("failed to clone cheatsheets: %w", err)
	}
	resp.Body.Close()
	// Online: use git if available
	cmd := exec.Command("git", "clone", "https://github.com/cheat/cheatsheets", dest)
	out, err := cmd.CombinedOutput()
	if err != nil {
		msg := strings.TrimSpace(string(out))
		if msg != "" {
			return fmt.Errorf("failed to clone cheatsheets: %s", msg)
		}
		return fmt.Errorf("failed to clone cheatsheets: %w", err)
	}
	return nil
}

func doInit() error {
	cfgPath, err := defaultConfigPath()
	if err != nil {
		return errExit(1, fmt.Sprintf("failed to read config paths: %v", err))
	}
	tmpl, err := generateConfig(cfgPath)
	if err != nil {
		return errExit(1, fmt.Sprintf("failed to read config paths: %v", err))
	}
	fmt.Println(tmpl)
	return nil
}

func doCompletion(shell string) error {
	switch shell {
	case "bash":
		fmt.Print(completionBash)
	case "zsh":
		fmt.Print(completionZsh)
	case "fish":
		fmt.Print(completionFish)
	case "powershell":
		fmt.Print(completionPowershell)
	default:
		return errExit(1, fmt.Sprintf("unsupported shell: %s (valid: bash, zsh, fish, powershell)", shell))
	}
	return nil
}

func generateConfig(cfgPath string) (string, error) {
	// editor detection
	editor := ""
	if v := os.Getenv("VISUAL"); v != "" {
		editor = v
	} else if v := os.Getenv("EDITOR"); v != "" {
		editor = v
	} else {
		for _, cand := range []string{"editor", "nano", "vim"} {
			if p, err := exec.LookPath(cand); err == nil {
				editor = p
				break
			}
		}
		if editor == "" {
			editor = "EDITOR_PATH"
		}
	}
	pager := ""
	if v := os.Getenv("PAGER"); v != "" {
		pager = v
	} else {
		for _, cand := range []string{"pager", "less", "more"} {
			if p, err := exec.LookPath(cand); err == nil {
				pager = p
				break
			}
		}
	}
	configDir := filepath.Dir(cfgPath)
	personal := filepath.Join(configDir, "cheatsheets", "personal")
	work := filepath.Join(configDir, "cheatsheets", "work")
	community := filepath.Join(configDir, "cheatsheets", "community")

	tmpl := `---
# The editor to use with 'cheat -e <sheet>'. Overridden by $VISUAL or $EDITOR.
editor: ` + editor + `

# Should 'cheat' always colorize output?
colorize: false

# Which 'chroma' colorscheme should be applied to the output?
# Options are available here:
#   https://github.com/alecthomas/chroma/tree/master/styles
style: monokai

# Which 'chroma' "formatter" should be applied?
# One of: "terminal", "terminal256", "terminal16m"
formatter: terminal256

# Through which pager should output be piped?
# 'less -FRX' is recommended on Unix systems
# 'more' is recommended on Windows
pager: ` + pager + `

# The paths at which cheatsheets are available. Tags associated with a cheatpath
# are automatically attached to all cheatsheets residing on that path.
#
# Whenever cheatsheets share the same title (like 'tar'), the most local
# cheatsheets (those which come later in this file) take precedence over the
# less local sheets. This allows you to create your own "overides" for
# "upstream" cheatsheets.
#
# But what if you want to view the "upstream" cheatsheets instead of your own?
# Cheatsheets may be filtered by 'tags' in combination with the '--tag' flag.
# 
# Example: 'cheat tar --tag=community' will display the 'tar' cheatsheet that
# is tagged as 'community' rather than your own.
#
# Paths that come earlier are considered to be the most "global", and paths
# that come later are considered to be the most "local". The most "local" paths
# take precedence.
#
# See: https://github.com/cheat/cheat/blob/master/doc/cheat.1.md#cheatpaths
cheatpaths:

  # Cheatsheets that are tagged "personal" are stored here by default:
  - name: personal
    path: ` + personal + `
    tags: [ personal ]
    readonly: false

  # Cheatsheets that are tagged "work" are stored here by default:
  - name: work
    path: ` + work + `
    tags: [ work ]
    readonly: false

  # Community cheatsheets (https://github.com/cheat/cheatsheets):
  # To install: git clone https://github.com/cheat/cheatsheets ` + community + `
  #- name: community
  #  path: ` + community + `
  #  tags: [ community ]
  #  readonly: true

  # You can also use glob patterns to automatically load cheatsheets from all
  # directories that match.
  #
  # Example: overload cheatsheets for projects under ~/src/github.com/example/*/
  #- name: example-projects
  #  path: ~/src/github.com/example/**/.cheat
  #  tags: [ example ]
  #  readonly: true`
	return tmpl, nil
}

// ---------- pager & colorize helpers ----------

func isTTY() bool {
	fi, err := os.Stdout.Stat()
	if err != nil {
		return false
	}
	return fi.Mode()&os.ModeCharDevice != 0
}

func effectiveColorize(cfg *Config, opts *options) bool {
	if opts.b("colorize") {
		return true
	}
	if cfg.Colorize && isTTY() {
		return true
	}
	return false
}

func outputThroughPager(cfg *Config, text string) error {
	if cfg.Pager == "" {
		fmt.Print(text)
		return nil
	}
	parts := strings.Fields(cfg.Pager)
	if len(parts) == 0 {
		fmt.Print(text)
		return nil
	}
	cmd := exec.Command(parts[0], parts[1:]...)
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr
	stdin, err := cmd.StdinPipe()
	if err != nil {
		return fmt.Errorf("failed to write to pager: %w", err)
	}
	if err := cmd.Start(); err != nil {
		return fmt.Errorf("failed to write to pager: %w", err)
	}
	_, writeErr := stdin.Write([]byte(text))
	closeErr := stdin.Close()
	waitErr := cmd.Wait()
	if writeErr != nil {
		return fmt.Errorf("failed to write to pager: %w", writeErr)
	}
	if closeErr != nil && waitErr == nil {
		// ignore close errors if wait ok? original likely reports wait err primarily
	}
	if waitErr != nil {
		return fmt.Errorf("failed to write to pager: %w", waitErr)
	}
	return nil
}

// format sheets as blocks "title (path)\n\t<indented text>" joined by blank line
func formatSheetBlocks(sheets []Sheet, cfg *Config, colorize bool, texts []string) string {
	var blocks []string
	for idx, s := range sheets {
		text := s.Text
		if texts != nil {
			text = texts[idx]
		}
		trimmed := strings.TrimSpace(text)
		var body string
		if colorize {
			// colorize the trimmed text; chroma tokenizes trimmed (with a trailing newline? it formats the exact string)
			// Original outputs show tokens for trimmed text without final newline handling beyond formatter.
			body = colorizeTextForBlock(trimmed, s, cfg)
		} else {
			body = trimmed
		}
		indented := "\t" + strings.ReplaceAll(body, "\n", "\n\t")
		var header string
		if colorize {
			header = fmt.Sprintf("%s \x1b[2m(%s)\x1b[0m", s.Title, s.CheatPath.Name)
		} else {
			header = fmt.Sprintf("%s (%s)", s.Title, s.CheatPath.Name)
		}
		blocks = append(blocks, header+"\n"+indented)
	}
	return strings.Join(blocks, "\n\n")
}

func colorizeTextForBlock(trimmed string, s Sheet, cfg *Config) string {
	// Chroma is fed the sheet text as-is; for block display the original trims *after*? Observed: leading tabs of first line removed due TrimSpace before display.
	// We colorize the trimmed string. If trimmed is empty, output empty.
	if trimmed == "" {
		return ""
	}
	return colorizeText(trimmed, s.Syntax, cfg)
}

// ---------- modes ----------

func doDirectories(cfg *Config, opts *options) error {
	cps := cfg.Cheatpaths
	if opts.changedFlag("path") {
		cps = filterCheatpathsByName(cps, opts.s("path"))
	}
	var buf strings.Builder
	w := tabwriter.NewWriter(&buf, 0, 0, 1, ' ', 0)
	for _, cp := range cps {
		fmt.Fprintf(w, "%s:\t%s\n", cp.Name, cp.Path)
	}
	w.Flush()
	return outputThroughPager(cfg, buf.String())
}

func loadAndFilter(cfg *Config, opts *options, pathFiltered []Cheatpath, applyTag bool) ([]Sheet, error) {
	sheets, err := loadSheets(pathFiltered)
	if err != nil {
		return nil, fmt.Errorf("failed to list cheatsheets: %w", err)
	}
	if applyTag && opts.changedFlag("tag") {
		sheets = filterByTag(sheets, opts.s("tag"))
	}
	return sheets, nil
}

func doDisplay(cfg *Config, opts *options, pathFiltered []Cheatpath) error {
	sheets, err := loadAndFilter(cfg, opts, pathFiltered, true)
	if err != nil {
		return err
	}
	title := opts.args[0]
	sheet, ok := findSheet(sheets, title)
	if !ok {
		fmt.Printf("No cheatsheet found for '%s'.\n", title)
		return errExitSilent(2)
	}
	text := sheet.Text
	if effectiveColorize(cfg, opts) {
		text = colorizeText(text, sheet.Syntax, cfg)
	}
	return outputThroughPager(cfg, text)
}

func doDisplayAll(cfg *Config, opts *options, pathFiltered []Cheatpath) error {
	sheets, err := loadAndFilter(cfg, opts, pathFiltered, true)
	if err != nil {
		return err
	}
	title := opts.args[0]
	matched := sheetsWithTitle(sheets, title)
	out := formatSheetBlocks(matched, cfg, effectiveColorize(cfg, opts), nil)
	if len(matched) > 0 {
		out += "\n"
	}
	return outputThroughPager(cfg, out)
}

func doList(cfg *Config, opts *options, pathFiltered []Cheatpath, brief bool) error {
	sheets, err := loadAndFilter(cfg, opts, pathFiltered, true)
	if err != nil {
		return err
	}
	// positional filter: case-insensitive regex on title
	if len(opts.args) == 1 {
		pattern := "(?i)" + opts.args[0]
		re, err := regexp.Compile(pattern)
		if err != nil {
			return fmt.Errorf("failed to compile regexp: %s, %v", pattern, err)
		}
		var filtered []Sheet
		for _, s := range sheets {
			if re.MatchString(s.Title) {
				filtered = append(filtered, s)
			}
		}
		sheets = filtered
	}
	if len(sheets) == 0 {
		return errExitSilent(2)
	}
	// sort by title, stable
	sort.SliceStable(sheets, func(i, j int) bool { return sheets[i].Title < sheets[j].Title })

	var buf strings.Builder
	w := tabwriter.NewWriter(&buf, 0, 0, 1, ' ', 0)
	if brief {
		fmt.Fprintln(w, "title:\ttags:")
		for _, s := range sheets {
			fmt.Fprintf(w, "%s\t%s\n", s.Title, strings.Join(sortedTags(s.Tags), ","))
		}
	} else {
		fmt.Fprintln(w, "title:\tfile:\ttags:")
		for _, s := range sheets {
			fmt.Fprintf(w, "%s\t%s\t%s\n", s.Title, s.Path, strings.Join(sortedTags(s.Tags), ","))
		}
	}
	w.Flush()
	return outputThroughPager(cfg, buf.String())
}

func doTags(cfg *Config, opts *options, pathFiltered []Cheatpath) error {
	// tags mode: NOT filtered by --tag
	sheets, err := loadAndFilter(cfg, opts, pathFiltered, false)
	if err != nil {
		return err
	}
	set := map[string]bool{}
	for _, s := range sheets {
		for _, t := range s.Tags {
			set[t] = true
		}
	}
	var tags []string
	for t := range set {
		tags = append(tags, t)
	}
	sort.Strings(tags)
	out := ""
	if len(tags) > 0 {
		out = strings.Join(tags, "\n") + "\n"
	}
	return outputThroughPager(cfg, out)
}

func doSearch(cfg *Config, opts *options, pathFiltered []Cheatpath) error {
	phrase := opts.s("search")
	var pattern string
	if opts.b("regex") {
		pattern = phrase
	} else {
		pattern = "(?i)" + phrase
	}
	re, err := regexp.Compile(pattern)
	if err != nil {
		return fmt.Errorf("failed to compile regexp: %s, %v", pattern, err)
	}
	sheets, err := loadAndFilter(cfg, opts, pathFiltered, true)
	if err != nil {
		return err
	}
	// optional positional: exact title filter
	if len(opts.args) == 1 {
		sheets = sheetsWithTitle(sheets, opts.args[0])
	}
	var resultSheets []Sheet
	var resultTexts []string
	for _, s := range sheets {
		paragraphs := strings.Split(s.Text, "\n\n")
		var matched []string
		for _, para := range paragraphs {
			if re.MatchString(para) {
				matched = append(matched, para)
			}
		}
		if len(matched) > 0 {
			resultSheets = append(resultSheets, s)
			resultTexts = append(resultTexts, strings.Join(matched, "\n\n"))
		}
	}
	out := formatSheetBlocks(resultSheets, cfg, effectiveColorize(cfg, opts), resultTexts)
	return outputThroughPager(cfg, out)
}

func validateCheatsheetName(name string) error {
	if name == "" {
		return fmt.Errorf("invalid cheatsheet name: cheatsheet name cannot be empty")
	}
	if filepath.IsAbs(name) {
		return fmt.Errorf("invalid cheatsheet name: cheatsheet name cannot be an absolute path")
	}
	if strings.Contains(name, "..") {
		return fmt.Errorf("invalid cheatsheet name: cheatsheet name cannot contain '..'")
	}
	if strings.HasPrefix(filepath.Base(name), ".") {
		return fmt.Errorf("invalid cheatsheet name: cheatsheet name cannot start with '.' (hidden files are not supported)")
	}
	return nil
}

func writeableCheatpath(cps []Cheatpath) (Cheatpath, bool) {
	// last non-readonly
	for i := len(cps) - 1; i >= 0; i-- {
		if !cps[i].Readonly {
			return cps[i], true
		}
	}
	return Cheatpath{}, false
}

func doEdit(cfg *Config, opts *options, pathFiltered []Cheatpath) error {
	name := opts.s("edit")
	if err := validateCheatsheetName(name); err != nil {
		return err
	}
	sheets, err := loadAndFilter(cfg, opts, pathFiltered, true)
	if err != nil {
		return err
	}
	existing, found := findSheet(sheets, name)
	var target string
	if found && !existing.CheatPath.Readonly {
		target = existing.Path
	} else {
		// destination cheatpath candidates are --path filtered only (pathFiltered), not tag filtered
		dest, ok := writeableCheatpath(pathFiltered)
		if !ok {
			return fmt.Errorf("failed to get writeable path: no writeable cheatpaths found")
		}
		target = filepath.Join(dest.Path, name)
		if found {
			// copy readonly sheet to target (overwrite)
			if err := os.MkdirAll(filepath.Dir(target), 0o755); err != nil {
				return fmt.Errorf("failed to create directory: %w", err)
			}
			data, err := os.ReadFile(existing.Path)
			if err != nil {
				return fmt.Errorf("failed to read file: %w", err)
			}
			if err := os.WriteFile(target, data, 0o644); err != nil {
				return fmt.Errorf("failed to write file: %w", err)
			}
		} else {
			if err := os.MkdirAll(filepath.Dir(target), 0o755); err != nil {
				return fmt.Errorf("failed to create directory: %w", err)
			}
		}
	}
	// invoke editor
	editorStr := cfg.Editor
	parts := strings.Fields(editorStr)
	if len(parts) == 0 {
		return fmt.Errorf("failed to edit cheatsheet: no editor set")
	}
	cmd := exec.Command(parts[0], append(parts[1:], target)...)
	cmd.Stdin = os.Stdin
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr
	if err := cmd.Run(); err != nil {
		return fmt.Errorf("failed to edit cheatsheet: %w", err)
	}
	return nil
}

func doRm(cfg *Config, opts *options, pathFiltered []Cheatpath) error {
	name := opts.s("rm")
	if err := validateCheatsheetName(name); err != nil {
		return err
	}
	sheets, err := loadAndFilter(cfg, opts, pathFiltered, true)
	if err != nil {
		return err
	}
	sheet, ok := findSheet(sheets, name)
	if !ok {
		return errExit(2, fmt.Sprintf("No cheatsheet found for '%s'.", name))
	}
	if sheet.CheatPath.Readonly {
		return errExit(1, fmt.Sprintf("cheatsheet '%s' is read-only.", name))
	}
	if err := os.Remove(sheet.Path); err != nil {
		return err
	}
	return nil
}

// ---------- update (git) ----------

func doUpdate(cfg *Config, opts *options, pathFiltered []Cheatpath) error {
	failed := false
	for _, cp := range pathFiltered {
		status, isErr := updateCheatpath(cp.Path)
		line := fmt.Sprintf("%s: %s\n", cp.Name, status)
		if isErr {
			fmt.Fprint(os.Stderr, line)
			failed = true
		} else {
			fmt.Print(line)
		}
	}
	if failed {
		return errExitSilent(1)
	}
	return nil
}

func gitCmd(dir string, args ...string) (string, error) {
	cmd := exec.Command("git", append([]string{"-C", dir}, args...)...)
	out, err := cmd.CombinedOutput()
	return strings.TrimSpace(string(out)), err
}

func updateCheatpath(path string) (string, bool) {
	// Determine git repo: .git must exist (dir or file) and git rev-parse works with GIT_DIR discovery only at this dir.
	// Use `git -C path rev-parse --git-dir`; but this would find parent repos. The original go-git PlainOpen only opens repo at exact path.
	// So first require path/.git exists.
	gitPath := filepath.Join(path, ".git")
	if _, err := os.Stat(gitPath); err != nil {
		return "skipped (not a git repository)", false
	}
	// validate repo at this path
	if _, err := gitCmd(path, "rev-parse", "--git-dir"); err != nil {
		return "skipped (not a git repository)", false
	}
	// check git-dir resolves to this .git (roughly) to avoid parent repo case when .git is bogus file etc handled above by rev-parse error
	// remote origin?
	if _, err := gitCmd(path, "remote", "get-url", "origin"); err != nil {
		return "error (remote not found)", true
	}
	// dirty?
	out, err := gitCmd(path, "status", "--porcelain")
	if err == nil && out != "" {
		return "skipped (dirty worktree)", false
	}
	// pull: fetch then fast-forward to upstream if configured, else origin/<current-branch>
	branch, err := gitCmd(path, "rev-parse", "--abbrev-ref", "HEAD")
	if err != nil || branch == "" || branch == "HEAD" {
		// detached / unborn
		// Try a plain pull; let git decide
		if out, err := gitCmd(path, "pull"); err != nil {
			return fmt.Sprintf("error (%s)", firstLine(out)), true
		}
		return "ok", false
	}
	if _, err := gitCmd(path, "fetch", "origin"); err != nil {
		// Map common errors
		out2, _ := gitCmd(path, "fetch", "origin") // rerun to get message? avoid; use previous via different approach below
		_ = out2
		return "error (failed to fetch)", true
	}
	// Determine remote branch
	remoteRef := "origin/" + branch
	if _, err := gitCmd(path, "rev-parse", "--verify", remoteRef); err != nil {
		return "error (reference not found)", true
	}
	// fast-forward merge
	if out, err := gitCmd(path, "merge", "--ff-only", remoteRef); err != nil {
		msg := firstLine(out)
		if strings.Contains(out, "Not possible to fast-forward") || strings.Contains(out, "non-fast-forward") || strings.Contains(out, "fatal:") {
			// go-git returns "non-fast-forward update" style error
			return "error (non-fast-forward update)", true
		}
		if msg == "" {
			msg = "merge failed"
		}
		return fmt.Sprintf("error (%s)", msg), true
	}
	return "ok", false
}

func firstLine(s string) string {
	s = strings.TrimSpace(s)
	if idx := strings.Index(s, "\n"); idx >= 0 {
		return strings.TrimSpace(s[:idx])
	}
	return s
}
