			// validate prev parse
			if _, err := parseFlags(prev); err != nil {
				return completeParseError(prev, err)
			}
			return completeFlagValue(def)
		}
		// Flag value via last prev token expecting a value
		if def, parsePrev, ok := flagExpectingValue(prev); ok {
			if _, err := parseFlags(parsePrev); err != nil {
				return completeParseError(parsePrev, err)
			}
			return completeFlagValue(def)
		}
	}

	// Parse prev args for errors / positional count / used flags
	opts, err := parseFlags(prev)
	if err != nil {
		return completeParseError(prev, err)
	}

	// Flag name completion
	if !terminated && strings.HasPrefix(toComplete, "-") && toComplete != "--=" {
		completions := flagNameCompletions(toComplete, opts, noDesc)
		for _, c := range completions {
			fmt.Println(c)
		}
		fmt.Println(":4")
		fmt.Fprintln(os.Stderr, "Completion ended with directive: ShellCompDirectiveNoFileComp")
		return 0
	}

	// Positional completion
	// Special: after -- , original gives sheets regardless (observed -- --tag "")
	if !terminated && len(opts.args) >= 1 {
		fmt.Println(":4")
		fmt.Fprintln(os.Stderr, "Completion ended with directive: ShellCompDirectiveNoFileComp")
		return 0
	}
	titles := completionSheetTitles()
	for _, t := range titles {
		fmt.Println(t)
	}
	fmt.Println(":4")
	fmt.Fprintln(os.Stderr, "Completion ended with directive: ShellCompDirectiveNoFileComp")
	return 0
}

func completeParseError(args []string, err error) int {
	fmt.Println(":0")
	fmt.Fprintf(os.Stderr, "[Debug] [Error] Error while parsing flags from args [%s]: %v\n", strings.Join(args, " "), err)
	fmt.Fprintln(os.Stderr, "Completion ended with directive: ShellCompDirectiveDefault")
	return 0
}

func flagFromEqualsToken(token string) (*flagDef, bool) {
	if strings.HasPrefix(token, "--") {
		s := token[2:]
		eq := strings.Index(s, "=")
		if eq < 0 {
			return nil, false
		}
		name := s[:eq]
		if name == "" {
			return nil, false
		}
		def := flagByLong(name)
		return def, true
	}
	if strings.HasPrefix(token, "-") && len(token) >= 2 {
		// shorthand with = : -t=..., -c=...
		r, size := utf8.DecodeRuneInString(token[1:])
		rest := token[1+size:]
		if strings.HasPrefix(rest, "=") {
			def := flagByShort(r)
			return def, true
		}
	}
	return nil, false
}

// flagExpectingValue determines (cobra-style) whether last prev token is a flag waiting for a separate value.
// returns def, args to parse for validation (excluding that flag token), ok
func flagExpectingValue(prev []string) (*flagDef, []string, bool) {
	if len(prev) == 0 {
		return nil, nil, false
	}
	last := prev[len(prev)-1]
	restPrev := prev[:len(prev)-1]
	// If there's a -- terminator before last, caller handles terminated
	if strings.HasPrefix(last, "--") && last != "--" {
		if strings.Contains(last, "=") {
			return nil, nil, false
		}
		def := flagByLong(last[2:])
		if def != nil && !def.isBool {
			return def, restPrev, true
		}
		// unknown long will be caught by parse of full prev
		return nil, nil, false
	}
	if strings.HasPrefix(last, "-") && last != "-" && last != "--" {
		if strings.Contains(last, "=") {
			return nil, nil, false
		}
		// cobra heuristic: last shorthand rune in the group
		s := last[1:]
		r, _ := utf8.DecodeLastRuneInString(s)
		def := flagByShort(r)
		if def != nil && !def.isBool {
			// Cobra treats even -pt as t expecting value. But if the group is like -pwork, last rune k is not a flag, so no.
			// However if earlier part is exactly a string flag with attached value whose last char coincides with a string-flag shorthand,
			// cobra still appears to use last-rune heuristic (observed -pt)
			return def, restPrev, true
		}
		return nil, nil, false
	}
	return nil, nil, false
}

func completeFlagValue(def *flagDef) int {
	switch def.long {
	case "tag":
		tags := completionTags()
		for _, t := range tags {
			fmt.Println(t)
		}
		fmt.Println(":4")
		fmt.Fprintln(os.Stderr, "Completion ended with directive: ShellCompDirectiveNoFileComp")
		return 0
	case "path":
		names := completionPathNames()
		for _, n := range names {
			fmt.Println(n)
		}
		fmt.Println(":4")
		fmt.Fprintln(os.Stderr, "Completion ended with directive: ShellCompDirectiveNoFileComp")
		return 0
	case "edit", "rm":
		titles := completionSheetTitles()
		for _, t := range titles {
			fmt.Println(t)
		}
		fmt.Println(":4")
		fmt.Fprintln(os.Stderr, "Completion ended with directive: ShellCompDirectiveNoFileComp")
		return 0
	default:
		fmt.Println(":0")
		fmt.Fprintln(os.Stderr, "Completion ended with directive: ShellCompDirectiveDefault")
		return 0
	}
}

func flagNameCompletions(toComplete string, opts *options, noDesc bool) []string {
	// Used flags (by long) are excluded
	var out []string
	for _, def := range flagDefs {
		if opts != nil && opts.changed[def.long] {
			continue
		}
		longTok := "--" + def.long
		if strings.HasPrefix(longTok, toComplete) {
			if noDesc {
				out = append(out, longTok)
			} else {
				out = append(out, longTok+"\t"+def.usage)
			}
		}
		if def.short != "" {
			shortTok := "-" + def.short
			// Only include shorthand when toComplete is single-dash style (not "--...")
			if !strings.HasPrefix(toComplete, "--") && strings.HasPrefix(shortTok, toComplete) {
				if noDesc {
					out = append(out, shortTok)
				} else {
					out = append(out, shortTok+"\t"+def.usage)
				}
			}
		}
	}
	return out
}

func completionLoadConfig() *Config {
	cfg, _, found, err := resolveConfig()
	if err != nil || !found || cfg == nil {
		return nil
	}
	return cfg
}

func completionSheetTitles() []string {
	cfg := completionLoadConfig()
	if cfg == nil {
		return nil
	}
	sheets, err := loadSheets(cfg.Cheatpaths)
	if err != nil {
		return nil
	}
	set := map[string]bool{}
	for _, s := range sheets {
		set[s.Title] = true
	}
	var out []string
	for t := range set {
		out = append(out, t)
	}
	sort.Strings(out)
	return out
}

func completionTags() []string {
	cfg := completionLoadConfig()
	if cfg == nil {
		return nil
	}
	sheets, err := loadSheets(cfg.Cheatpaths)
	if err != nil {
		return nil
	}
	set := map[string]bool{}
	for _, s := range sheets {
		for _, t := range s.Tags {
			set[t] = true
		}
	}
	var out []string
	for t := range set {
		out = append(out, t)
	}
	sort.Strings(out)
	return out
}

func completionPathNames() []string {
	cfg := completionLoadConfig()
	if cfg == nil {
		return nil
	}
	var out []string
	for _, cp := range cfg.Cheatpaths {
		out = append(out, cp.Name)
	}
	return out
}
