import subprocess, os, shutil
REF="/workspace/executable"; MINE="/tmp/mycheat"; H="/tmp/insthome"
fails=[]
def snap(root):
    out={}
    if not os.path.exists(root): return out
    for cur,dirs,files in os.walk(root):
        dirs.sort(); files.sort()
        for d in dirs: out[os.path.relpath(os.path.join(cur,d),root)]=("dir",)
        for f in files:
            p=os.path.join(cur,f); out[os.path.relpath(p,root)]=("file",open(p,'rb').read())
    return out

def runonce(exe,args,envx,inp,cwd,prepare):
    shutil.rmtree(H,ignore_errors=True); os.makedirs(H)
    if os.path.exists("/tmp/instcwd"): shutil.rmtree("/tmp/instcwd")
    os.makedirs("/tmp/instcwd")
    if prepare: prepare()
    env={k:v for k,v in os.environ.items() if k not in ["CHEAT_CONFIG_PATH","XDG_CONFIG_HOME","VISUAL","EDITOR","PAGER"]}
    env["HOME"]=H; env["PAGER"]="cat"
    if envx: env.update(envx)
    r=subprocess.run([exe]+args,input=inp,capture_output=True,env=env,cwd=cwd or "/tmp")
    return (r.returncode,r.stdout,r.stderr), (snap(H),snap("/tmp/instcwd"))

def compare(label,args,envx=None,inp=None,cwd=None,prepare=None):
    inp_b = inp.encode() if isinstance(inp,str) else inp
    a,sa=runonce(REF,args,envx,inp_b,cwd,prepare)
    b,sb=runonce(MINE,args,envx,inp_b,cwd,prepare)
    # Ignore FS if one has clone network differences? Compare all
    if a!=b or sa!=sb:
        fails.append(label); print("DIFF",label,args,envx,repr(inp))
        if a!=b: print(" REF",a); print(" MINE",b)
        if sa!=sb:
            for side,x,y in [("HOME",sa[0],sb[0]),("CWD",sa[1],sb[1])]:
