import pathlib
p=pathlib.Path('main.go'); s=p.read_text()
start=s.find('\t// remote origin?')
end=s.find('\nfunc firstLine')
assert start!=-1 and end!=-1
new='''\t// dirty?
\tout, err := gitCmd(path, "status", "--porcelain")
\tif err == nil && out != "" {
\t\treturn "skipped (dirty worktree)", false
\t}
\t// remote origin?
\tif _, err := gitCmd(path, "remote", "get-url", "origin"); err != nil {
\t\treturn "error (remote not found)", true
\t}
\t// fetch
\tif fout, err := gitCmd(path, "fetch", "origin"); err != nil {
\t\tif strings.Contains(fout, "does not appear to be a git repository") || strings.Contains(fout, "Could not read from remote repository") {
\t\t\treturn "error (repository not found)", true
\t\t}
\t\tif strings.Contains(fout, "couldn't find remote ref") || strings.Contains(fout, "could not find remote ref") {
\t\t\treturn "error (reference not found)", true
\t\t}
\t\tmsg := firstLine(fout)
\t\tif msg == "" {
\t\t\tmsg = "failed to fetch"
\t\t}
\t\treturn fmt.Sprintf("error (%s)", msg), true
\t}
\tbranch, err := gitCmd(path, "rev-parse", "--abbrev-ref", "HEAD")
\tif err != nil || branch == "" || branch == "HEAD" {
\t\t// detached or unborn HEAD: fast-forward to FETCH_HEAD if available
\t\tif _, ferr := gitCmd(path, "rev-parse", "--verify", "FETCH_HEAD"); ferr == nil {
\t\t\tif mout, merr := gitCmd(path, "merge", "--ff-only", "FETCH_HEAD"); merr != nil {
\t\t\t\tif strings.Contains(mout, "Not possible to fast-forward") || strings.Contains(mout, "non-fast-forward") {
\t\t\t\t\treturn "error (non-fast-forward update)", true
\t\t\t\t}
\t\t\t\tmsg := firstLine(mout)
\t\t\t\tif msg == "" { msg = "merge failed" }
\t\t\t\treturn fmt.Sprintf("error (%s)", msg), true
\t\t\t}
\t\t}
\t\treturn "ok", false
\t}
\tremoteRef := "origin/" + branch
\tif _, err := gitCmd(path, "rev-parse", "--verify", remoteRef); err != nil {
\t\treturn "error (reference not found)", true
\t}
\tif out, err := gitCmd(path, "merge", "--ff-only", remoteRef); err != nil {
\t\tmsg := firstLine(out)
\t\tif strings.Contains(out, "Not possible to fast-forward") || strings.Contains(out, "non-fast-forward") || strings.Contains(out, "fatal:") {
\t\t\treturn "error (non-fast-forward update)", true
\t\t}
\t\tif msg == "" {
\t\t\tmsg = "merge failed"
\t\t}
\t\treturn fmt.Sprintf("error (%s)", msg), true
\t}
\treturn "ok", false
}
'''
s=s[:start]+new+s[end:]
p.write_text(s)
