// findMatchingParen returns index of ')' matching '(' at openIdx in text, or -1
func findMatchingParen(text string, openIdx int) int {
	depth := 0
	i := openIdx
	for i < len(text) {
		c := text[i]
		switch c {
		case '\\':
			i += 2
			continue
		case '\'':
			j := i + 1
			for j < len(text) && text[j] != '\'' {
				j++
			}
			i = j + 1
			continue
		case '"':
			j := i + 1
			for j < len(text) {
				if text[j] == '\\' {
					j += 2
					continue
				}
				if text[j] == '"' {
					break
				}
				j++
			}
			i = j + 1
			continue
		case '`':
			j := i + 1
			for j < len(text) && text[j] != '`' {
				if text[j] == '\\' {
					j++
				}
				j++
			}
			i = j + 1
			continue
		case '(':
			depth++
		case ')':
			depth--
			if depth == 0 {
				return i
			}
		}
		i++
	}
	return -1
}

func findMatchingBrace(text string, openIdx int) int {
