func lexBacktick(text string, i int) ([]ctoken, int) {
	// text[i]=='`'
	j := i + 1
	for j < len(text) {
		if text[j] == '\\' && j+1 < len(text) {
			j += 2
			continue
		}
		if text[j] == '`' {
			break
		}
		j++
	}
	var toks []ctoken
	toks = append(toks, ctoken{tStringBacktick, "`"})
	if j >= len(text) {
		toks = append(toks, lexBash(text[i+1:])...)
		return toks, len(text)
	}
	toks = append(toks, lexBash(text[i+1:j])...)
	toks = append(toks, ctoken{tStringBacktick, "`"})
	return toks, j + 1
}

func lexBashDoubleQuoted(text string, i int) ([]ctoken, int) {
	// text[i]=='"'
	var toks []ctoken
	start := i
	j := i + 1
	flush := func(upto int) {
		if upto > start {
			toks = append(toks, ctoken{tStringDouble, text[start:upto]})
		}
	}
	for j < len(text) {
		c := text[j]
		if c == '\\' && j+1 < len(text) {
			j += 2
			continue
		}
		if c == '"' {
			j++
			flush(j)
			return toks, j
		}
		if c == '`' {
			flush(j)
			nt, ni := lexBacktick(text, j)
			toks = append(toks, nt...)
