cat > /tmp/bashlexer.go.txt <<'GOEOF'
// ---------- Bash lexer (approximation of Chroma's) ----------

var bashKeywords = map[string]bool{
	"if": true, "then": true, "else": true, "elif": true, "fi": true, "case": true, "esac": true,
	"for": true, "while": true, "until": true, "do": true, "done": true, "function": true,
	"return": true, "select": true, "time": true, "coproc": true,
}
var bashBuiltins = map[string]bool{
	"echo": true, "cd": true, "pwd": true, "export": true, "source": true, "alias": true,
	"unalias": true, "set": true, "unset": true, "shift": true, "test": true, "eval": true, "exec": true,
	"exit": true, "read": true, "local": true, "declare": true, "typeset": true, "let": true, "printf": true,
	"break": true, "continue": true, "trap": true, "umask": true, "wait": true, "jobs": true, "fg": true, "bg": true,
	"kill": true, "type": true, "hash": true, "help": true, "history": true, "command": true,
	"builtin": true, "enable": true, "getopts": true, "mapfile": true, "readarray": true, "shopt": true,
}

var varRe = regexp.MustCompile(`^\$([A-Za-z_][A-Za-z0-9_]*|[0-9@*#?$!_-])`)

func isSpaceByte(c byte) bool { return c == ' ' || c == '\t' || c == '\r' }
func isWordByte(c byte) bool {
	return c >= 'a' && c <= 'z' || c >= 'A' && c <= 'Z' || c >= '0' && c <= '9' || c == '_'
}
func isIdent(s string) bool {
	if s == "" {
		return false
	}
	for i := 0; i < len(s); i++ {
		c := s[i]
		if i == 0 {
			if !(c >= 'a' && c <= 'z' || c >= 'A' && c <= 'Z' || c == '_') {
				return false
			}
		} else if !isWordByte(c) {
			return false
		}
	}
	return true
}

// findMatchingParen returns index of ')' matching '(' at openIdx in text, or -1
func findMatchingParen(text string, openIdx int) int {
	depth := 0
	i := openIdx
	for i < len(text) {
		c := text[i]
		switch c {
		case '\\':
			i += 2
			continue
		case '\'':
			j := i + 1
			for j < len(text) && text[j] != '\'' {
				j++
			}
			i = j + 1
			continue
		case '"':
			j := i + 1
			for j < len(text) {
				if text[j] == '\\' {
					j += 2
					continue
				}
				if text[j] == '"' {
					break
				}
				j++
			}
			i = j + 1
			continue
		case '`':
			j := i + 1
			for j < len(text) && text[j] != '`' {
				if text[j] == '\\' {
					j++
				}
				j++
			}
			i = j + 1
			continue
		case '(':
			depth++
		case ')':
			depth--
			if depth == 0 {
				return i
			}
		}
		i++
	}
	return -1
}

func findMatchingBrace(text string, openIdx int) int {
	// openIdx indexes '{' of '${'
	depth := 0
	i := openIdx
	for i < len(text) {
		if text[i] == '\\' {
			i += 2
			continue
		}
		if text[i] == '{' {
			depth++
		} else if text[i] == '}' {
			depth--
			if depth == 0 {
				return i
			}
		}
		i++
	}
	return -1
}

func lexBashArithmetic(text string) []ctoken {
	var toks []ctoken
	i := 0
	for i < len(text) {
		c := text[i]
		if c == '\n' {
			toks = append(toks, ctoken{tText, "\n"})
			i++
			continue
		}
		if isSpaceByte(c) {
			j := i
			for j < len(text) && isSpaceByte(text[j]) {
				j++
			}
			toks = append(toks, ctoken{tText, text[i:j]})
			i = j
			continue
		}
		if c >= '0' && c <= '9' {
			j := i
			for j < len(text) && text[j] >= '0' && text[j] <= '9' {
				j++
			}
			toks = append(toks, ctoken{tNumber, text[i:j]})
			i = j
			continue
		}
		if c == '$' {
			nt, ni, ok := lexBashExpansion(text, i)
			if ok {
				toks = append(toks, nt...)
				i = ni
				continue
			}
		}
		if isWordByte(c) {
			j := i
			for j < len(text) && isWordByte(text[j]) {
				j++
			}
			toks = append(toks, ctoken{tNameVariable, text[i:j]})
			i = j
			continue
		}
		if strings.ContainsRune("+-*/%<>=&|^!~?:", rune(c)) {
			j := i
			for j < len(text) && strings.ContainsRune("+-*/%<>=&|^!~?:", rune(text[j])) {
				j++
			}
			toks = append(toks, ctoken{tOperator, text[i:j]})
			i = j
			continue
		}
		// parens/commas
		toks = append(toks, ctoken{tPunctuation, text[i : i+1]})
		i++
	}
	return toks
}

// lexBashExpansion handles $((..)), $(..), ${..}, $var at text[i]=='$'; returns tokens and new index
func lexBashExpansion(text string, i int) ([]ctoken, int, bool) {
	rest := text[i:]
	if strings.HasPrefix(rest, "$((") {
		// find closing ))
		depth := 0
		j := i + 3
		closeIdx := -1
		for j < len(text) {
			if text[j] == '(' {
				depth++
				j++
				continue
			}
			if text[j] == ')' {
				if depth == 0 {
					if j+1 < len(text) && text[j+1] == ')' {
						closeIdx = j
						break
					}
					// single ) inside? treat as mismatch, break without close
					break
				}
				depth--
				j++
				continue
			}
			j++
		}
		var toks []ctoken
		toks = append(toks, ctoken{tKeyword, "$(("})
		if closeIdx < 0 {
			toks = append(toks, lexBashArithmetic(text[i+3:])...)
			return toks, len(text), true
		}
		toks = append(toks, lexBashArithmetic(text[i+3:closeIdx])...)
		toks = append(toks, ctoken{tKeyword, "))"})
		return toks, closeIdx + 2, true
	}
	if strings.HasPrefix(rest, "$(") {
		closeIdx := findMatchingParen(text, i+1)
		var toks []ctoken
		toks = append(toks, ctoken{tKeyword, "$("})
		if closeIdx < 0 {
			toks = append(toks, lexBash(text[i+2:])...)
			return toks, len(text), true
		}
		toks = append(toks, lexBash(text[i+2:closeIdx])...)
		toks = append(toks, ctoken{tKeyword, ")"})
		return toks, closeIdx + 1, true
	}
	if strings.HasPrefix(rest, "${") {
		closeIdx := findMatchingBrace(text, i+1)
		var toks []ctoken
		toks = append(toks, ctoken{tString, "${"})
		if closeIdx < 0 {
			toks = append(toks, lexParamInner(text[i+2:])...)
			return toks, len(text), true
		}
		toks = append(toks, lexParamInner(text[i+2:closeIdx])...)
		toks = append(toks, ctoken{tString, "}"})
		return toks, closeIdx + 1, true
	}
	if m := varRe.FindString(rest); m != "" {
		return []ctoken{{tNameVariable, m}}, i + len(m), true
	}
	return nil, i, false
}

func lexParamInner(inner string) []ctoken {
	if inner == "" {
		return nil
	}
	var toks []ctoken
	i := 0
	// leading name / special
	if inner[0] >= '0' && inner[0] <= '9' {
		j := 0
		for j < len(inner) && inner[j] >= '0' && inner[j] <= '9' {
			j++
		}
		toks = append(toks, ctoken{tNameVariable, inner[:j]})
		i = j
	} else if isWordByte(inner[0]) && !(inner[0] >= '0' && inner[0] <= '9') {
		j := 0
		for j < len(inner) && isWordByte(inner[j]) {
			j++
		}
		toks = append(toks, ctoken{tNameVariable, inner[:j]})
		i = j
	} else if strings.ContainsRune("@*#?$!-", rune(inner[0])) {
		toks = append(toks, ctoken{tNameVariable, inner[:1]})
		i = 1
	}
	for i < len(inner) {
		if inner[i] == '$' {
			if nt, ni, ok := lexBashExpansion(inner, i); ok {
				toks = append(toks, nt...)
				i = ni
				continue
			}
		}
		j := i
		for j < len(inner) && inner[j] != '$' {
			j++
		}
		if j == i {
			j++
		}
		toks = append(toks, ctoken{tString, inner[i:j]})
		i = j
	}
	return toks
}

func lexBacktick(text string, i int) ([]ctoken, int) {
	// text[i]=='`'
	j := i + 1
	for j < len(text) {
		if text[j] == '\\' && j+1 < len(text) {
			j += 2
			continue
		}
		if text[j] == '`' {
			break
		}
		j++
	}
	var toks []ctoken
	toks = append(toks, ctoken{tStringBacktick, "`"})
	if j >= len(text) {
		toks = append(toks, lexBash(text[i+1:])...)
		return toks, len(text)
	}
	toks = append(toks, lexBash(text[i+1:j])...)
	toks = append(toks, ctoken{tStringBacktick, "`"})
	return toks, j + 1
}

func lexBashDoubleQuoted(text string, i int) ([]ctoken, int) {
	// text[i]=='"'
	var toks []ctoken
	start := i
	j := i + 1
	flush := func(upto int) {
		if upto > start {
			toks = append(toks, ctoken{tStringDouble, text[start:upto]})
		}
	}
	for j < len(text) {
		c := text[j]
		if c == '\\' && j+1 < len(text) {
			j += 2
			continue
		}
		if c == '"' {
			j++
			flush(j)
			return toks, j
		}
		if c == '`' {
			flush(j)
			nt, ni := lexBacktick(text, j)
			toks = append(toks, nt...)
			j = ni
			start = j
			continue
		}
		if c == '$' {
			if nt, ni, ok := lexBashExpansion(text, j); ok {
				flush(j)
				toks = append(toks, nt...)
				j = ni
				start = j
				continue
			}
		}
		j++
	}
	flush(j)
	return toks, j
}

type heredocSpec struct {
	delim string
	stripTabs bool
}

func lexBash(text string) []ctoken {
	var toks []ctoken
	i := 0
	atWordStart := true
	atCommandStart := true
	expectAssignValue := false
	var heredocs []heredocSpec

	markValueConsumed := func() {
		if expectAssignValue {
			expectAssignValue = false
			atCommandStart = true
		}
	}

	for i < len(text) {
		c := text[i]
		if c == '\n' {
			toks = append(toks, ctoken{tText, "\n"})
			i++
			atWordStart = true
			atCommandStart = true
			expectAssignValue = false
			// consume heredoc bodies
			for len(heredocs) > 0 {
				hd := heredocs[0]
				heredocs = heredocs[1:]
				for i < len(text) {
					lineEnd := strings.IndexByte(text[i:], '\n')
					var line string
					var next int
					hasNL := lineEnd >= 0
					if hasNL {
						line = text[i : i+lineEnd]
						next = i + lineEnd // index of newline
					} else {
						line = text[i:]
						next = len(text)
					}
					cmp := line
					if hd.stripTabs {
						cmp = strings.TrimLeft(cmp, "\t")
					}
					if cmp == hd.delim {
						if line != "" {
							toks = append(toks, ctoken{tString, line})
						}
						i = next
						break
					}
					// body line including newline
					if hasNL {
						toks = append(toks, ctoken{tString, text[i:next+1]})
						i = next + 1
					} else {
						if line != "" {
							toks = append(toks, ctoken{tString, line})
						}
						i = next
					}
				}
			}
			continue
		}
		// heredoc start
		if c == '<' && strings.HasPrefix(text[i:], "<<") {
			if strings.HasPrefix(text[i:], "<<<") {
				toks = append(toks, ctoken{tString, "<<<"})
				i += 3
				atWordStart = true
				markValueConsumed()
				continue
			}
			j := i + 2
			stripTabs := false
			if j < len(text) && text[j] == '-' {
				stripTabs = true
				j++
			}
			k := j
			for k < len(text) && (text[k] == ' ' || text[k] == '\t') {
				k++
			}
			// delimiter, optionally quoted
			delimStart := k
			var delim string
			if k < len(text) && (text[k] == '\'' || text[k] == '"') {
				q := text[k]
				k++
				ds := k
				for k < len(text) && text[k] != q && text[k] != '\n' {
					k++
				}
				delim = text[ds:k]
				if k < len(text) && text[k] == q {
					k++
				}
			} else {
				for k < len(text) && (isWordByte(text[k]) || text[k] == '.' || text[k] == '-') {
					k++
				}
				delim = text[delimStart:k]
			}
			if delim != "" {
				toks = append(toks, ctoken{tString, text[i:k]})
				heredocs = append(heredocs, heredocSpec{delim: delim, stripTabs: stripTabs})
				i = k
				atWordStart = true
				markValueConsumed()
				continue
			}
			// fall through to word handling
		}
		if c == '#' && atWordStart {
			j := i
			for j < len(text) && text[j] != '\n' {
				j++
			}
			toks = append(toks, ctoken{tComment, text[i:j]})
			i = j
			atWordStart = false
			atCommandStart = false
			continue
		}
		if isSpaceByte(c) {
			j := i
			for j < len(text) && isSpaceByte(text[j]) {
				j++
			}
			toks = append(toks, ctoken{tText, text[i:j]})
			i = j
			atWordStart = true
			continue
		}
		if c == '\'' {
			j := i + 1
			for j < len(text) && text[j] != '\'' {
				j++
			}
			if j < len(text) {
				j++
			}
			toks = append(toks, ctoken{tStringSingle, text[i:j]})
			i = j
			atWordStart = false
			markValueConsumed()
			continue
		}
		if c == '"' {
			nt, ni := lexBashDoubleQuoted(text, i)
			toks = append(toks, nt...)
			i = ni
			atWordStart = false
			markValueConsumed()
			continue
		}
		if c == '`' {
			nt, ni := lexBacktick(text, i)
			toks = append(toks, nt...)
			i = ni
			atWordStart = false
			markValueConsumed()
			continue
		}
		if c == '$' {
			if nt, ni, ok := lexBashExpansion(text, i); ok {
				toks = append(toks, nt...)
				i = ni
				atWordStart = false
				markValueConsumed()
				continue
			}
		}
		// multi-char operators
		if strings.HasPrefix(text[i:], "&&") || strings.HasPrefix(text[i:], "||") || strings.HasPrefix(text[i:], "==") || strings.HasPrefix(text[i:], "!=") || strings.HasPrefix(text[i:], "<=") || strings.HasPrefix(text[i:], ">=") {
			toks = append(toks, ctoken{tOperator, text[i : i+2]})
			i += 2
			atWordStart = true
			atCommandStart = true
			expectAssignValue = false
			continue
		}
		if c == '=' {
			j := i
			for j < len(text) && text[j] == '=' {
				j++
			}
			toks = append(toks, ctoken{tOperator, text[i:j]})
			i = j
			atWordStart = true
			// An '=' that immediately followed an assignment name is detected by expectAssignValue being set by caller below;
			continue
		}
		if c == '|' || c == '&' || c == ';' {
			j := i
			for j < len(text) && text[j] == c {
				j++
			}
			toks = append(toks, ctoken{tPunctuation, text[i:j]})
			i = j
			atWordStart = true
			atCommandStart = true
			expectAssignValue = false
			continue
		}
		if c == '(' || c == ')' {
			toks = append(toks, ctoken{tOperator, text[i : i+1]})
			i++
			atWordStart = true
			if c == '(' {
				atCommandStart = true
			}
			markValueConsumed()
			continue
		}
		if c == '[' {
			if strings.HasPrefix(text[i:], "[[") {
				toks = append(toks, ctoken{tOperator, "[["})
				i += 2
				atWordStart = true
				continue
			}
			if atWordStart && (i+1 >= len(text) || isSpaceByte(text[i+1])) {
				toks = append(toks, ctoken{tOperator, "["})
				i++
				atWordStart = true
				continue
			}
		}
		if c == ']' {
			if strings.HasPrefix(text[i:], "]]") {
				toks = append(toks, ctoken{tOperator, "]]"})
				i += 2
				atWordStart = true
				continue
			}
			if atWordStart {
				toks = append(toks, ctoken{tOperator, "]"})
				i++
				atWordStart = true
				continue
			}
		}
		if (c == '{' || c == '}') && atWordStart {
			nextOK := i+1 >= len(text) || isSpaceByte(text[i+1]) || text[i+1] == '\n' || text[i+1] == ';'
			if nextOK {
				toks = append(toks, ctoken{tOperator, text[i : i+1]})
				i++
				atWordStart = true
				if c == '{' {
					atCommandStart = true
				}
				markValueConsumed()
				continue
			}
		}
		// number: integer followed by whitespace or EOF
		if atWordStart && c >= '0' && c <= '9' {
			j := i
			for j < len(text) && text[j] >= '0' && text[j] <= '9' {
				j++
			}
			if j >= len(text) || text[j] == '\n' || isSpaceByte(text[j]) {
				toks = append(toks, ctoken{tNumber, text[i:j]})
				i = j
				atWordStart = false
				markValueConsumed()
				continue
			}
		}
		// word run
		j := i
		stoppedAtEquals := false
		for j < len(text) {
			ch := text[j]
			if ch == '\n' || isSpaceByte(ch) || ch == '\'' || ch == '"' || ch == '`' || ch == '|' || ch == '&' || ch == ';' || ch == '(' || ch == ')' {
				break
			}
			if ch == '<' && j > i && strings.HasPrefix(text[j:], "<<") {
				break
			}
			if ch == '$' && j > i {
				break
			}
			if ch == '=' && j > i {
				segment := text[i:j]
				if isIdent(segment) || strings.HasPrefix(segment, "-") {
					stoppedAtEquals = true
					break
				}
			}
			if ch == '\\' && j+1 < len(text) && text[j+1] != '\n' {
				j += 2
				continue
			}
			j++
		}
		if j == i {
			j = i + 1
		}
		word := text[i:j]
		typ := tText
		isAssignName := stoppedAtEquals && isIdent(word)
		if isAssignName {
			typ = tNameVariable
		} else if bashKeywords[word] && atWordStart && !expectAssignValue {
			typ = tKeyword
		} else if atCommandStart && bashBuiltins[word] && !expectAssignValue {
			typ = tNameBuiltin
		}
		wasExpect := expectAssignValue
		toks = append(toks, ctoken{typ, word})
		i = j
		atWordStart = false
		if isAssignName {
			// next loop will emit '='; set flag so the value after isn't treated as builtin/keyword
			// We signal via a closure variable set when '=' consumed: use expectAssignValue as "pending equals" marker here,
			// then '=' branch converts it into value expectation. Simplify: set expectAssignValue now; '=' branch leaves it true; first value token clears via markValueConsumed.
			expectAssignValue = true
		} else if wasExpect {
			expectAssignValue = false
			atCommandStart = true
		} else {
			atCommandStart = false
		}
	}
	return toks
}

