# Add lexYAML and wire it
cat >> color.go <<'GOEOF'

func lexYAML(text string) []ctoken {
	var toks []ctoken
	for len(text) > 0 {
		line := text
		hasNL := false
		if idx := strings.IndexByte(text, '\n'); idx >= 0 {
			line = text[:idx]
			hasNL = true
			text = text[idx+1:]
		} else {
			text = ""
		}
		toks = append(toks, lexYAMLLine(line)...)
		if hasNL {
			toks = append(toks, ctoken{tText, "\n"})
		}
	}
	return toks
}

func lexYAMLLine(line string) []ctoken {
	var toks []ctoken
	// leading spaces
	i := 0
	for i < len(line) && line[i] == ' ' {
		i++
	}
	if i > 0 {
		toks = append(toks, ctoken{tText, line[:i]})
	}
	rest := line[i:]
	if strings.HasPrefix(rest, "#") {
		toks = append(toks, ctoken{tComment, rest})
		return toks
	}
	// mapping key
	colon := strings.Index(rest, ":")
	if colon > 0 && !strings.ContainsAny(rest[:colon], "[]{}") {
		key := rest[:colon]
		toks = append(toks, ctoken{tKeywordNamespace, key})
		toks = append(toks, ctoken{tPunctuation, ":"})
		rest = rest[colon+1:]
		toks = append(toks, lexYAMLValue(rest)...)
		return toks
	}
	toks = append(toks, lexYAMLValue(rest)...)
	return toks
}

func lexYAMLValue(s string) []ctoken {
	var toks []ctoken
	i := 0
	for i < len(s) {
		c := s[i]
		if c == ' ' || c == '\t' {
			j := i
			for j < len(s) && (s[j] == ' ' || s[j] == '\t') {
				j++
			}
			toks = append(toks, ctoken{tText, s[i:j]})
			i = j
			continue
		}
		if c == '#' && i > 0 {
			toks = append(toks, ctoken{tComment, s[i:]})
			break
		}
		if c == '\'' || c == '"' {
			j := i + 1
			for j < len(s) && s[j] != c {
				if c == '"' && s[j] == '\\' {
					j++
				}
				j++
			}
			if j < len(s) {
				j++
			}
			toks = append(toks, ctoken{tString, s[i:j]})
			i = j
			continue
		}
		if strings.ContainsRune("[]{}(),:-", rune(c)) && !(c == '-' && i+1 < len(s) && s[i+1] != ' ') {
			// '-' list marker only if followed by space/EOL; colon handled as punct here too
			if c == '-' && !(i+1 == len(s) || s[i+1] == ' ') {
				// part of scalar below
			} else {
				toks = append(toks, ctoken{tPunctuation, s[i : i+1]})
				i++
				continue
			}
		}
		j := i
		for j < len(s) && !strings.ContainsRune(" \t[]{}(),", rune(s[j])) {
			// stop before comment separated
			j++
		}
		if j == i {
			j++
		}
		toks = append(toks, ctoken{tNumber, s[i:j]})
		i = j
	}
	return toks
}
