	var toks []ctoken
	for len(text) > 0 {
		line := text
		hasNL := false
		if idx := strings.IndexByte(text, '\n'); idx >= 0 {
			line = text[:idx]
			hasNL = true
			text = text[idx+1:]
		} else {
			text = ""
