func makeStyle(def *rgb, entries map[int]styleEntry) styleSet {
	// fill color256=-1 default already zero in many entries; entries constructed with rgbPtr but color256 0 would mean index0. So normalize: if color256==0 and fg isn't black-ish index0, set -1 unless fg is exactly palette 0 (#000000) - none here are pure black fg, so set all zero to -1.
	for k, v := range entries {
		if v.color256 == 0 {
			v.color256 = -1
			entries[k] = v
		}
	}
	if def != nil {
		d := styleEntry{fg: def, color256: -1}
		return styleSet{entries: entries, def: d, hasDef: true}
	}
	return styleSet{entries: entries}
}

