					k++
				}
				if k == i {
					// '=' itself or other punctuation
					if c == '=' {
						toks = append(toks, ctoken{tOperator, "="})
						i++
					} else {
						toks = append(toks, ctoken{tPunctuation, text[i : i+1]})
						i++
					}
					continue
				}
