			toks = append(toks, ctoken{tPunctuation, "{"})
			inBlock = true
			expectProperty = true
			i++
			continue
		}
		if c == '}' {
			toks = append(toks, ctoken{tPunctuation, "}"})
			inBlock = false
			i++
			continue
		}
		if c == ';' {
			toks = append(toks, ctoken{tPunctuation, ";"})
			if inBlock {
				expectProperty = true
			}
			i++
			continue
		}
		if c == ':' {
			toks = append(toks, ctoken{tPunctuation, ":"})
			expectProperty = false
			i++
			continue
		}
