package main

import (
	"strings"
)

const (
	tGenericStrong = 100 + iota
	tGenericEmph
)

func lexJSON(text string) []ctoken {
	var toks []ctoken
	i := 0
	for i < len(text) {
		c := text[i]
		if c == '\n' {
			toks = append(toks, ctoken{tText, "\n"})
			i++
			continue
		}
		if isSpaceByte(c) {
			j := i
			for j < len(text) && isSpaceByte(text[j]) {
				j++
			}
			toks = append(toks, ctoken{tText, text[i:j]})
			i = j
			continue
		}
		if c == '"' {
			j := i + 1
			for j < len(text) && text[j] != '\n' {
				if text[j] == '\\' && j+1 < len(text) {
					j += 2
					continue
				}
				if text[j] == '"' {
					j++
					break
				}
				j++
			}
			typ := tString
			k := j
			for k < len(text) && isSpaceByte(text[k]) {
				k++
			}
			if k < len(text) && text[k] == ':' {
				typ = tKeywordNamespace
			}
			toks = append(toks, ctoken{typ, text[i:j]})
			i = j
			continue
		}
		if c == '-' || (c >= '0' && c <= '9') {
			j := i
			if text[j] == '-' {
				j++
			}
			for j < len(text) && (text[j] >= '0' && text[j] <= '9' || text[j] == '.' || text[j] == 'e' || text[j] == 'E' || text[j] == '+' || text[j] == '-') {
				j++
			}
			toks = append(toks, ctoken{tNumber, text[i:j]})
			i = j
			continue
		}
		if isWordByte(c) {
			j := i
			for j < len(text) && isWordByte(text[j]) {
				j++
			}
			w := text[i:j]
			typ := tText
			if w == "true" || w == "false" || w == "null" {
				typ = tKeyword
			}
			toks = append(toks, ctoken{typ, w})
			i = j
			continue
		}
		toks = append(toks, ctoken{tPunctuation, text[i : i+1]})
		i++
	}
	return toks
}

func lexHTML(text string, isXML bool) []ctoken {
	var toks []ctoken
	i := 0
	for i < len(text) {
		if strings.HasPrefix(text[i:], "<!--") {
			end := strings.Index(text[i+4:], "-->")
			j := len(text)
			if end >= 0 {
				j = i + 4 + end + 3
			}
			toks = append(toks, ctoken{tComment, text[i:j]})
			i = j
			continue
		}
		if text[i] == '<' {
			j := i + 1
			closing := false
			if j < len(text) && text[j] == '/' {
				closing = true
				j++
			}
			nameStart := j
			for j < len(text) && (isWordByte(text[j]) || text[j] == '-' || text[j] == ':') {
				j++
			}
			name := text[nameStart:j]
			if name == "" {
				toks = append(toks, ctoken{tPunctuation, "<"})
				i++
				continue
			}
			if isXML {
				prefix := "<"
				if closing {
					prefix = "</"
				}
				// include '>' in a closing tag token when immediately present
				if closing && j < len(text) && text[j] == '>' {
					toks = append(toks, ctoken{tKeywordNamespace, prefix + name + ">"})
					i = j + 1
					continue
				}
				toks = append(toks, ctoken{tKeywordNamespace, prefix + name})
			} else {
				prefix := "<"
				if closing {
					prefix = "</"
				}
				toks = append(toks, ctoken{tPunctuation, prefix})
				toks = append(toks, ctoken{tKeywordNamespace, name})
			}
			i = j
			// inside tag until >
			for i < len(text) {
				c := text[i]
				if c == '\n' {
					toks = append(toks, ctoken{tText, "\n"})
					i++
					continue
				}
				if isSpaceByte(c) {
					k := i
					for k < len(text) && isSpaceByte(text[k]) {
						k++
					}
					toks = append(toks, ctoken{tText, text[i:k]})
					i = k
					continue
				}
				if c == '>' {
					typ := tPunctuation
					if isXML {
						typ = tKeywordNamespace
					}
					toks = append(toks, ctoken{typ, ">"})
					i++
					break
				}
				if c == '/' && i+1 < len(text) && text[i+1] == '>' {
					typ := tPunctuation
					if isXML {
						typ = tKeywordNamespace
					}
					toks = append(toks, ctoken{typ, "/>"})
					i += 2
					break
				}
				if c == '"' || c == '\'' {
					q := c
					k := i + 1
					for k < len(text) && text[k] != q && text[k] != '\n' {
						k++
					}
					if k < len(text) && text[k] == q {
						k++
					}
					toks = append(toks, ctoken{tString, text[i:k]})
					i = k
					continue
				}
				// attribute name (XML includes '=' in the same token)
				k := i
				for k < len(text) && !isSpaceByte(text[k]) && text[k] != '\n' && text[k] != '>' && text[k] != '=' && text[k] != '/' {
					k++
				}
				if k == i {
					// '=' itself or other punctuation
					if c == '=' {
						toks = append(toks, ctoken{tOperator, "="})
						i++
					} else {
						toks = append(toks, ctoken{tPunctuation, text[i : i+1]})
						i++
					}
					continue
				}
				attr := text[i:k]
				if isXML && k < len(text) && text[k] == '=' {
					attr += "="
					k++
					toks = append(toks, ctoken{tNameFunction, attr})
					i = k
					continue
				}
				toks = append(toks, ctoken{tNameFunction, attr})
				i = k
			}
			continue
		}
		// text up to next '<' or newline
		j := i
		for j < len(text) && text[j] != '<' && text[j] != '\n' {
			j++
		}
		if j == i {
			j++
		}
		toks = append(toks, ctoken{tText, text[i:j]})
		i = j
		if i < len(text) && text[i] == '\n' {
			toks = append(toks, ctoken{tText, "\n"})
			i++
		}
	}
	return toks
}

func lexCSS(text string) []ctoken {
	var toks []ctoken
	i := 0
	inBlock := false
	expectProperty := false
	for i < len(text) {
		c := text[i]
		if strings.HasPrefix(text[i:], "/*") {
			end := strings.Index(text[i+2:], "*/")
			j := len(text)
			if end >= 0 {
				j = i + 2 + end + 2
			}
			toks = append(toks, ctoken{tComment, text[i:j]})
			i = j
			continue
		}
		if c == '\n' {
			toks = append(toks, ctoken{tText, "\n"})
			i++
			continue
		}
		if isSpaceByte(c) {
			j := i
			for j < len(text) && isSpaceByte(text[j]) {
				j++
			}
			toks = append(toks, ctoken{tText, text[i:j]})
			i = j
			continue
		}
		if c == '"' || c == '\'' {
			j := i + 1
			for j < len(text) && text[j] != c && text[j] != '\n' {
				if text[j] == '\\' {
					j++
				}
				j++
			}
			if j < len(text) && text[j] == c {
				j++
			}
			toks = append(toks, ctoken{tString, text[i:j]})
			i = j
			continue
		}
		if c == '{' {
			toks = append(toks, ctoken{tPunctuation, "{"})
			inBlock = true
			expectProperty = true
			i++
			continue
		}
		if c == '}' {
			toks = append(toks, ctoken{tPunctuation, "}"})
			inBlock = false
			i++
			continue
		}
		if c == ';' {
			toks = append(toks, ctoken{tPunctuation, ";"})
			if inBlock {
				expectProperty = true
			}
			i++
			continue
		}
		if c == ':' {
			toks = append(toks, ctoken{tPunctuation, ":"})
			expectProperty = false
			i++
			continue
		}
		if c >= '0' && c <= '9' || (c == '-' && i+1 < len(text) && text[i+1] >= '0' && text[i+1] <= '9') {
			j := i
			if text[j] == '-' {
				j++
			}
			for j < len(text) && (text[j] >= '0' && text[j] <= '9' || text[j] == '.') {
				j++
			}
			// units as separate punctuation-ish? consume unit letters into a following text token would split number; keep number only digits
			toks = append(toks, ctoken{tNumber, text[i:j]})
			i = j
			continue
		}
		if c == '#' {
			j := i + 1
			for j < len(text) && isWordByte(text[j]) {
				j++
			}
			typ := tNumber
			if !inBlock {
				typ = tNameFunction
			}
			toks = append(toks, ctoken{typ, text[i:j]})
			i = j
			continue
		}
		if isWordByte(c) || c == '-' || c == '.' || c == '*' {
			j := i
			for j < len(text) && (isWordByte(text[j]) || text[j] == '-' || text[j] == '.') {
				j++
			}
			if j == i {
				j++
			}
			w := text[i:j]
			typ := tText
			if !inBlock {
				typ = tKeywordNamespace
			} else {
				typ = tKeyword
			}
			_ = expectProperty
			toks = append(toks, ctoken{typ, w})
			i = j
			continue
		}
		toks = append(toks, ctoken{tPunctuation, text[i : i+1]})
		i++
	}
	return toks
}

func lexMarkdown(text string) []ctoken {
	var toks []ctoken
	lines := strings.SplitAfter(text, "\n")
	for _, rawLine := range lines {
		if rawLine == "" {
			continue
		}
		hasNL := strings.HasSuffix(rawLine, "\n")
		line := strings.TrimSuffix(rawLine, "\n")
		if strings.HasPrefix(line, "#") {
			if line != "" {
				toks = append(toks, ctoken{tText, line})
			}
		} else {
			// inline scan
			i := 0
			bufStart := 0
			flush := func(upto int) {
				if upto > bufStart {
					toks = append(toks, ctoken{tText, line[bufStart:upto]})
				}
			}
			for i < len(line) {
				if strings.HasPrefix(line[i:], "**") {
					if end := strings.Index(line[i+2:], "**"); end >= 0 {
						flush(i)
						j := i + 2 + end + 2
						toks = append(toks, ctoken{tGenericStrong, line[i:j]})
						i = j
						bufStart = i
						continue
					}
				}
				if strings.HasPrefix(line[i:], "__") {
					if end := strings.Index(line[i+2:], "__"); end >= 0 {
						flush(i)
						j := i + 2 + end + 2
						toks = append(toks, ctoken{tGenericStrong, line[i:j]})
						i = j
						bufStart = i
						continue
					}
				}
				if line[i] == '`' {
					if end := strings.Index(line[i+1:], "`"); end >= 0 {
						flush(i)
						j := i + 1 + end + 1
						toks = append(toks, ctoken{tString, line[i:j]})
						i = j
						bufStart = i
						continue
					}
				}
				if line[i] == '[' {
					if closeBracket := strings.Index(line[i:], "]("); closeBracket > 0 {
						if closeParen := strings.Index(line[i+closeBracket:], ")"); closeParen >= 0 {
							flush(i)
							linkTextStart := i + 1
							linkTextEnd := i + closeBracket
							urlStart := linkTextEnd + 2
							urlEnd := i + closeBracket + closeParen
							toks = append(toks, ctoken{tText, "["})
							toks = append(toks, ctoken{tKeywordNamespace, line[linkTextStart:linkTextEnd]})
							toks = append(toks, ctoken{tText, "]("})
							toks = append(toks, ctoken{tNameFunction, line[urlStart:urlEnd]})
							i = urlEnd // ')' will be flushed as text below
							bufStart = i
							continue
						}
					}
				}
				i++
			}
			flush(len(line))
		}
		if hasNL {
			toks = append(toks, ctoken{tText, "\n"})
		}
	}
	return toks
}

func lexDiff(text string) []ctoken {
	var toks []ctoken
	for len(text) > 0 {
		line := text
		hasNL := false
		if idx := strings.IndexByte(text, '\n'); idx >= 0 {
			line = text[:idx]
			hasNL = true
			text = text[idx+1:]
		} else {
			text = ""
		}
		typ := tText
		switch {
		case strings.HasPrefix(line, "---") || strings.HasPrefix(line, "-"):
			typ = tOperator
		case strings.HasPrefix(line, "+++") || strings.HasPrefix(line, "+"):
			typ = tNameFunction
		case strings.HasPrefix(line, "@@"):
			typ = tComment
		}
		if line != "" {
			toks = append(toks, ctoken{typ, line})
		}
		if hasNL {
			// diff lexer includes newline in line tokens effectively (no separate empty text token observed);
			// append it to the just-emitted token via a same-type-separate hack: merge by extending last token.
			if len(toks) > 0 {
				toks[len(toks)-1].value += "\n"
			} else {
				toks = append(toks, ctoken{tText, "\n"})
			}
		}
	}
	return toks
}

func lexINI(text string) []ctoken {
	var toks []ctoken
	for len(text) > 0 {
		line := text
		hasNL := false
		if idx := strings.IndexByte(text, '\n'); idx >= 0 {
			line = text[:idx]
			hasNL = true
			text = text[idx+1:]
		} else {
			text = ""
		}
		trimmed := strings.TrimSpace(line)
		if strings.HasPrefix(trimmed, "[") && strings.HasSuffix(trimmed, "]") {
			toks = append(toks, ctoken{tKeyword, line})
		} else if strings.HasPrefix(trimmed, ";") || strings.HasPrefix(trimmed, "#") {
			toks = append(toks, ctoken{tComment, line})
		} else if eq := strings.Index(line, "="); eq > 0 {
			before := line[:eq]
			key := strings.TrimRight(before, " \t")
			trail := before[len(key):]
			toks = append(toks, ctoken{tNameFunction, key})
			if trail != "" {
				toks = append(toks, ctoken{tText, trail})
			}
			toks = append(toks, ctoken{tOperator, "="})
			rest := line[eq+1:]
			// leading space is a separate text token in the reference
			lead := 0
			for lead < len(rest) && (rest[lead] == ' ' || rest[lead] == '\t') {
				lead++
			}
			if lead > 0 {
				toks = append(toks, ctoken{tText, rest[:lead]})
			}
			if lead < len(rest) {
				toks = append(toks, ctoken{tString, rest[lead:]})
			}
		} else if line != "" {
			toks = append(toks, ctoken{tText, line})
		}
		if hasNL {
			toks = append(toks, ctoken{tText, "\n"})
		}
	}
	return toks
}

func lexMakefile(text string) []ctoken {
	var toks []ctoken
	for len(text) > 0 {
		line := text
		hasNL := false
		if idx := strings.IndexByte(text, '\n'); idx >= 0 {
			line = text[:idx]
			hasNL = true
			text = text[idx+1:]
		} else {
			text = ""
		}
		if strings.HasPrefix(line, "\t") {
			toks = append(toks, ctoken{tText, "\t"})
			rest := line[1:]
			if hasNL {
				rest += "\n"
			}
			toks = append(toks, lexBash(rest)...)
			// lexBash added the newline token already
			continue
		}
		if strings.HasPrefix(strings.TrimSpace(line), "#") {
			toks = append(toks, ctoken{tComment, line})
		} else if colon := strings.Index(line, ":"); colon > 0 && !strings.Contains(line[:colon], "=") {
			toks = append(toks, ctoken{tNameFunction, line[:colon]})
			toks = append(toks, ctoken{tOperator, ":"})
			if colon+1 < len(line) {
				toks = append(toks, lexBash(line[colon+1:])...)
			}
		} else if line != "" {
			toks = append(toks, lexBash(line)...)
		}
		if hasNL {
			toks = append(toks, ctoken{tText, "\n"})
		}
	}
	return toks
}

func lexDockerfile(text string) []ctoken {
	var toks []ctoken
	for len(text) > 0 {
		line := text
		hasNL := false
		if idx := strings.IndexByte(text, '\n'); idx >= 0 {
			line = text[:idx]
			hasNL = true
			text = text[idx+1:]
		} else {
			text = ""
		}
		trimmedLeft := strings.TrimLeft(line, " \t")
		lead := line[:len(line)-len(trimmedLeft)]
		if lead != "" {
			toks = append(toks, ctoken{tText, lead})
		}
		if strings.HasPrefix(trimmedLeft, "#") {
			toks = append(toks, ctoken{tComment, trimmedLeft})
		} else if trimmedLeft != "" {
			// first word = instruction
			end := 0
			for end < len(trimmedLeft) && !isSpaceByte(trimmedLeft[end]) {
				end++
			}
			instr := trimmedLeft[:end]
			toks = append(toks, ctoken{tKeyword, instr})
			rest := trimmedLeft[end:]
			if rest != "" {
				upper := strings.ToUpper(instr)
				switch upper {
				case "FROM":
					// space, then image as a string token
					spEnd := 0
					for spEnd < len(rest) && isSpaceByte(rest[spEnd]) {
						spEnd++
					}
					if spEnd > 0 {
						toks = append(toks, ctoken{tText, rest[:spEnd]})
					}
					if spEnd < len(rest) {
						toks = append(toks, ctoken{tString, rest[spEnd:]})
					}
				case "RUN", "CMD", "ENTRYPOINT":
					toks = append(toks, lexBash(rest)...)
				default:
					toks = append(toks, ctoken{tText, rest})
				}
			}
		}
		if hasNL {
			toks = append(toks, ctoken{tError, "\n"})
		}
	}
	return toks
}

func lexConsole(text string) []ctoken {
	var toks []ctoken
	for len(text) > 0 {
		line := text
		hasNL := false
		if idx := strings.IndexByte(text, '\n'); idx >= 0 {
			line = text[:idx]
			hasNL = true
			text = text[idx+1:]
		} else {
			text = ""
		}
		if strings.HasPrefix(line, "$") {
			toks = append(toks, ctoken{tNameVariable, "$"})
			if len(line) > 1 {
				toks = append(toks, ctoken{tText, line[1:]})
			}
		} else if strings.HasPrefix(line, "#") && len(line) > 1 && line[1] == ' ' {
			// root prompt is ambiguous with comments; treat "# " similarly in console only if it looks like a prompt is unknowable. Leave as text.
			toks = append(toks, ctoken{tText, line})
		} else if line != "" {
			toks = append(toks, ctoken{tText, line})
		}
		if hasNL {
			toks = append(toks, ctoken{tText, "\n"})
		}
	}
	return toks
}
