\t\t\treturn "error (non-fast-forward update)", true
\t\t}
\t\tif msg == "" {
\t\t\tmsg = "merge failed"
\t\t}
\t\treturn fmt.Sprintf("error (%s)", msg), true
\t}
'''
s=s[:start]+new+s[end:]
# Add helper before isAncestorOrEqual
s=s.replace('func isAncestorOrEqual(dir, a, b string) bool {','''func fetchHeadTarget(path string) string {
	gitDir, err := gitCmd(path, "rev-parse", "--git-dir")
	if err != nil {
		return ""
	}
	if !filepath.IsAbs(gitDir) {
		gitDir = filepath.Join(path, gitDir)
	}
	data, err := os.ReadFile(filepath.Join(gitDir, "FETCH_HEAD"))
	if err != nil {
		return ""
	}
	type entry struct{ hash, marker, desc string }
	var entries []entry
	for _, line := range strings.Split(strings.TrimSpace(string(data)), "\\n") {
		if strings.TrimSpace(line) == "" {
			continue
		}
		parts := strings.Split(line, "\\t")
		e := entry{hash: strings.TrimSpace(parts[0])}
		if len(parts) > 1 {
			e.marker = strings.TrimSpace(parts[1])
		}
		if len(parts) > 2 {
			e.desc = parts[2]
		}
		entries = append(entries, e)
	}
	for _, e := range entries {
		if e.marker != "not-for-merge" {
			return e.hash
		}
	}
	// All entries are not-for-merge: resolve the remote's HEAD branch.
	if out, err := gitCmd(path, "ls-remote", "--symref", "origin", "HEAD"); err == nil {
		for _, line := range strings.Split(out, "\\n") {
			fields := strings.Fields(line)
			if len(fields) >= 2 && fields[0] == "ref:" {
				branch := strings.TrimPrefix(fields[1], "refs/heads/")
				for _, e := range entries {
					if strings.Contains(e.desc, "branch '"+branch+"'") {
						return e.hash
					}
				}
				ref := "origin/" + branch
				if _, verr := gitCmd(path, "rev-parse", "--verify", ref); verr == nil {
					return ref
				}
			}
			if len(fields) >= 2 && fields[1] == "HEAD" {
				return fields[0]
			}
		}
	}
	if len(entries) > 0 {
		return entries[0].hash
	}
	return ""
}

func isAncestorOrEqual(dir, a, b string) bool {''')
